{
  "name": "testcase-validator",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "dev": "tsx --env-file-if-exists=.env src/server.ts",
    "typecheck": "tsc",
    "test": "vitest run"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "^1.30.0",
    "fastify": "^5.2.1",
    "pg": "^8.23.0"
  },
  "devDependencies": {
    "@types/node": "^22.13.1",
    "@types/pg": "^8.21.0",
    "pg-mem": "^3.0.14",
    "tsx": "^4.23.12",
    "typescript": "^5.7.3",
    "vitest": "^3.0.5"
  }
}

import type {
  NewProject,
  NewTestSuite,
  Placement,
  ProjectChanges,
  ProjectDeletion,
  TestCase,
  TestLinkClient,
  TestLinkContent,
  TestSuiteChanges,
} from '../src/testlink-client.js'

/** What the stub answers a Project listing with, for a test to read back. */
export const stubProjects = [{ id: '12', name: 'Wireless', prefix: 'WL' }]

/** What the stub answers a Test Case listing with, for a test to read back. */
export const stubTestCasesInSuite = [{ id: '5074', name: 'Guest joins the open SSID' }]

/** Substitutes for TestLink, recording what was written through and what it holds. */
export class StubTestLinkClient implements TestLinkClient {
  readonly written: { placement: Placement; testCase: TestCase }[] = []
  readonly updated: { id: string; testCase: TestCase }[] = []
  readonly deleted: string[] = []
  readonly suitesWritten: { projectId: string; suite: NewTestSuite; parentSuiteId?: string }[] = []
  readonly listed: { projectId: string; parentSuiteId?: string }[] = []

  readonly projectsWritten: NewProject[] = []
  readonly projectsUpdated: { projectId: string; changes: ProjectChanges }[] = []

  private readonly heldCases = new Map<string, TestCase>()
  private readonly heldSuites = new Set<string>()
  /** The Projects TestLink holds, each against the prefix a delete must restate. */
  private readonly heldProjects = new Map<string, string>()

  /** Standing in for TestLink being unreachable, which is not a Rejection. */
  constructor(private readonly reachable = true) {}

  /**
   * Puts content in TestLink without it passing the write path, which is how
   * content the Rules would fire on comes to be there at all. Held content and
   * written content are kept apart deliberately: a read is set up by saying
   * what TestLink holds, never by first getting content past the Rules.
   */
  hold(id: string, testCase: TestCase): void {
    this.heldCases.set(id, testCase)
  }

  /** Says TestLink holds this Test Suite, so a write placed in it has somewhere to land. */
  holdSuite(suiteId: string): void {
    this.heldSuites.add(suiteId)
  }

  /** Says TestLink holds this Project, so a Suite created in it has somewhere to land. */
  holdProject(projectId: string, prefix = 'WL'): void {
    this.heldProjects.set(projectId, prefix)
  }

  async createTestCase(
    placement: Placement,
    testCase: TestCase,
  ): Promise<{ id: string } | undefined> {
    this.reach()

    if (!this.heldSuites.has(placement.suiteId)) {
      return undefined
    }

    this.written.push({ placement, testCase })
    return { id: `testlink-${this.written.length}` }
  }

  async getTestCase(id: string): Promise<TestCase | undefined> {
    this.reach()

    return this.heldCases.get(id)
  }

  async updateTestCase(id: string, testCase: TestCase): Promise<boolean> {
    this.reach()

    if (!this.heldCases.has(id)) {
      return false
    }

    this.heldCases.set(id, testCase)
    this.updated.push({ id, testCase })
    return true
  }

  async deleteTestCase(id: string): Promise<boolean> {
    this.reach()

    if (!this.heldCases.delete(id)) {
      return false
    }

    this.deleted.push(id)
    return true
  }

  async listProjects(): Promise<TestLinkContent> {
    this.reach()

    return stubProjects
  }

  async createProject(project: NewProject): Promise<{ id: string }> {
    this.reach()
    this.projectsWritten.push(project)

    const id = `project-${this.projectsWritten.length}`
    this.heldProjects.set(id, project.prefix)
    return { id }
  }

  async updateProject(projectId: string, changes: ProjectChanges): Promise<boolean> {
    this.reach()

    if (!this.heldProjects.has(projectId)) {
      return false
    }

    this.projectsUpdated.push({ projectId, changes })
    return true
  }

  async deleteProject(projectId: string, confirmPrefix: string): Promise<ProjectDeletion> {
    this.reach()

    const prefix = this.heldProjects.get(projectId)

    if (prefix === undefined) {
      return 'absent'
    }

    if (prefix !== confirmPrefix) {
      return 'unconfirmed'
    }

    this.heldProjects.delete(projectId)
    return 'deleted'
  }

  async listTestSuites(
    projectId: string,
    parentSuiteId?: string,
  ): Promise<TestLinkContent | undefined> {
    this.reach()
    this.listed.push({ projectId, parentSuiteId })

    if (!this.heldProjects.has(projectId)) {
      return undefined
    }

    return [...this.heldSuites].map((id) => ({ id }))
  }

  async listTestCasesInSuite(suiteId: string): Promise<TestLinkContent | undefined> {
    this.reach()

    if (!this.heldSuites.has(suiteId)) {
      return undefined
    }

    return stubTestCasesInSuite
  }

  async createTestSuite(
    projectId: string,
    suite: NewTestSuite,
    parentSuiteId?: string,
  ): Promise<{ id: string } | undefined> {
    this.reach()

    if (!this.heldProjects.has(projectId)) {
      return undefined
    }

    this.suitesWritten.push({ projectId, suite, parentSuiteId })
    const id = `suite-${this.suitesWritten.length}`
    this.heldSuites.add(id)
    return { id }
  }

  async updateTestSuite(
    _projectId: string,
    suiteId: string,
    _changes: TestSuiteChanges,
  ): Promise<boolean> {
    this.reach()

    return this.heldSuites.has(suiteId)
  }

  async deleteTestSuite(suiteId: string): Promise<boolean> {
    this.reach()

    return this.heldSuites.delete(suiteId)
  }

  private reach(): void {
    if (!this.reachable) {
      throw new Error('TestLink is unreachable.')
    }
  }
}

