import type {
  DocumentStore,
  ListedReferenceDocument,
  ReferenceDocument,
} from '../src/reference-document.js'

/** Substitutes for the database, holding the Reference Documents a test serves. */
export class StubDocumentStore implements DocumentStore {
  private readonly held = new Map<string, ReferenceDocument>()

  /** Standing in for the database being unreachable, which is not a Rejection. */
  constructor(private readonly reachable = true) {}

  /**
   * Puts a Reference Document in the store without it passing any Rule, which is
   * how content the Rules fire on comes to be there at all. Documents are written
   * by an operator rather than through this API, so this is the only way one
   * arrives.
   */
  hold(id: string, document: ReferenceDocument): this {
    this.held.set(id, document)
    return this
  }

  async listDocuments(): Promise<ListedReferenceDocument[]> {
    this.reach()

    return [...this.held].map(([id, { title }]) => ({ id, title }))
  }

  async getDocument(id: string): Promise<ReferenceDocument | undefined> {
    this.reach()

    return this.held.get(id)
  }

  private reach(): void {
    if (!this.reachable) {
      throw new Error('The database is unreachable.')
    }
  }
}

import type { StoredRule } from '../src/rule-set.js'

/**
 * The Rules a test binds an app with, written the way an operator writes a row
 * rather than the way the database answers with one. A row carries eight
 * columns and a test cares about four of them, so the rest are filled in here —
 * `flanked` null on a Term, no Exceptions unless the test is about Exceptions.
 *
 * These build a row that has already been accepted. A test about a row the
 * schema would refuse writes the row out in full, because the point of it is the
 * column that is wrong.
 */
interface Written {
  id: string
  field: string
  reason: string
  exceptions?: string[]
  /** A Test Case unless the test says otherwise, which is what most of them check. */
  contentKind?: 'testCase' | 'referenceDocument'
}

/** A Term Rule: a word or phrase, matched in any casing. */
export function term({ term, ...written }: Written & { term: string }): StoredRule {
  return { ...row(written), category: 'term', looksFor: term, flanked: null }
}

/** A Symbol Rule: one character, optionally narrowed to where whitespace flanks it. */
export function symbol({
  symbol,
  flanked = null,
  ...written
}: Written & { symbol: string; flanked?: 'whitespace' | null }): StoredRule {
  return { ...row(written), category: 'symbol', looksFor: symbol, flanked }
}

/** Everything a Term and a Symbol Rule hold alike, which is every column but the check itself. */
function row({
  id,
  field,
  reason,
  exceptions = [],
  contentKind = 'testCase',
}: Written): Omit<StoredRule, 'category' | 'looksFor' | 'flanked'> {
  return { ruleId: id, contentKind, field, reason, exceptions }
}

import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

import { newDb } from 'pg-mem'

import { queriesFrom } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'

/**
 * A file the repository ships, read rather than restated, so a test of what an
 * operator is told to do fails when what they are told changes. The operator
 * applies these by hand and nothing this project runs writes a row (ADR-0006),
 * so a test of them has to be a test of the files themselves — statements copied
 * in here would pass while the file an operator applies was broken.
 */
export function shipped(name: string): string {
  return readFileSync(fileURLToPath(new URL(`../${name}`, import.meta.url)), 'utf8')
}

/**
 * A Postgres that runs in this process, holding no tables until the schema is
 * applied — a database an operator has not set up yet. The stubbed seam beside
 * this one proves the store asks for the right things; this one proves the
 * statements it asks with are statements a Postgres accepts — the schema, the
 * parameters and the reading of rows, none of which a stub can tell the truth
 * about.
 */
export function empty(): Queries {
  const pg = newDb().adapters.createPg()

  // Through the production adapter, not a copy of it, so what the tests
  // exercise is the same reading of rows the server does.
  return queriesFrom(new pg.Client())
}

import { buildApp } from './app.js'
import { expectedTestLinkMcp, McpTestLinkClient } from './mcp-testlink-client.js'
import { connectToPostgres, PostgresStore } from './postgres-store.js'
import { required } from './setting.js'
import { connectToTestLinkMcp } from './stdio-tool-caller.js'

/**
 * The database, which holds the Rules and the Reference Documents. Read only
 * from here: what is in it was written by an operator with SQL, and this project
 * ships nothing that writes to it (ADR-0006).
 */
const store = new PostgresStore(await connectToPostgres(required('DATABASE_URL')))

/**
 * Read once, here, and never again — the property ADR-0004 keeps when it moves
 * Rules out of a file. A database with none enabled in it is missing in the same
 * way an invalid Rule is: there is no point starting a server that would accept
 * every write it is given.
 */
const rules = await store.rules()

if (rules.length === 0) {
  throw new Error(
    'No enabled Rules are in the database, so the server will not start. Apply schema.sql and insert a Rule — the README has the statements.',
  )
}

/**
 * How to launch testlink-mcp. It documents two ways of being run — the
 * published container and a checkout of its source — so both are reachable
 * here; the container is the default because it is the documented one. The
 * arguments are read as JSON so that a path with a space in it survives, which
 * is also the shape every MCP client configuration writes them in.
 *
 * The container is pinned to the version the client calls rather than tracking
 * `latest`. A tag is not a version: Docker will not re-pull one it already
 * holds, so `latest` is whatever it meant the first time a host pulled it, and
 * a host that pulled before a tool existed keeps a server without it.
 */
function testLinkMcp(): { command: string; args: string[] } {
  const command = process.env.TESTLINK_MCP_COMMAND

  if (command === undefined) {
    return {
      command: 'docker',
      args: [
        'run',
        '--rm',
        '-i',
        '-e',
        'TESTLINK_URL',
        '-e',
        'TESTLINK_API_KEY',
        `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
      ],
    }
  }

  try {
    return { command, args: JSON.parse(required('TESTLINK_MCP_ARGS')) }
  } catch (error) {
    throw new Error(
      `TESTLINK_MCP_ARGS must be a JSON list of arguments, so the server will not start: ${
        (error as Error).message
      }`,
    )
  }
}

const tools = await connectToTestLinkMcp({
  ...testLinkMcp(),
  env: {
    ...process.env,
    TESTLINK_URL: required('TESTLINK_URL'),
    TESTLINK_API_KEY: required('TESTLINK_API_KEY'),
  } as Record<string, string>,
})

const app = buildApp({
  testlink: new McpTestLinkClient(tools, { authorLogin: required('TESTLINK_AUTHOR_LOGIN') }),
  documents: store,
  rules,
  // Violations and outages, and not a line per request: what is logged is what
  // an operator is meant to read, and request logging was not asked for.
  logger: { level: 'warn' },
})

await app.listen({ port: Number(process.env.PORT ?? 3000), host: '0.0.0.0' })

import pg from 'pg'

import type { Queries } from './queries.js'
import type {
  DocumentStore,
  ListedReferenceDocument,
  ReferenceDocument,
} from './reference-document.js'
import type { StoredRule } from './rule-set.js'

/**
 * Whether an operator has applied `schema.sql` to this database. Asked outright
 * rather than read out of the error a missing table would raise: absence is told
 * from unreachability by what the database says about itself, never by matching
 * the text of a failure.
 */
async function hasSchema(queries: Queries): Promise<boolean> {
  const rows = await queries.run(
    "select 1 from information_schema.tables where table_name = 'rules'",
  )

  return rows.length > 0
}

/**
 * The enabled Exceptions, gathered under the Rule each belongs to. Read in a
 * statement of its own rather than joined: a Rule with no Exception is the
 * common one, and a join would answer for it with a row of nulls to tell apart
 * from a row carrying a phrase.
 */
async function exceptionsByRule(queries: Queries): Promise<Map<number, string[]>> {
  const rows = await queries.run(
    'select rule, phrase from rule_exceptions where enabled order by id',
  )
  const byRule = new Map<number, string[]>()

  for (const row of rows) {
    const rule = Number(row.rule)
    const phrases = byRule.get(rule)

    if (phrases === undefined) {
      byRule.set(rule, [String(row.phrase)])
      continue
    }

    phrases.push(String(row.phrase))
  }

  return byRule
}

/**
 * The database, read only. This project makes no write to it at all (ADR-0006),
 * so there is no method here that could relax a Rule or author a Reference
 * Document — the server holds an object that cannot do either.
 *
 * Absence is an answer rather than a failure: a document the database holds
 * nothing under answers `undefined`, where the database being unreachable
 * throws out of `pg` and reaches the caller as a server error.
 */
export class PostgresStore implements DocumentStore {
  constructor(private readonly queries: Queries) {}

  /**
   * The enabled Rules, each carrying its enabled Exceptions. Read once at
   * startup and never again, which is the property ADR-0004 keeps: a running
   * server judges every Test Case by the Rules it started with.
   *
   * A disabled Rule is not read at all. It stops firing exactly as completely as
   * a deleted one would, and its row stays so a Violation logged against it can
   * still be explained (ADR-0007).
   *
   * A database the schema has never been applied to has no tables at all, which
   * is still "no Rules" and not an outage — so it answers none here and the
   * server says what to do, rather than dying on a missing table.
   */
  async rules(): Promise<StoredRule[]> {
    if (!(await hasSchema(this.queries))) {
      return []
    }

    const rows = await this.queries.run(
      'select id, rule_id, content_kind, field, category, looks_for, flanked, reason from rules where enabled order by id',
    )
    const exceptions = await exceptionsByRule(this.queries)

    return rows.map((row) => ({
      ruleId: String(row.rule_id),
      contentKind: String(row.content_kind),
      field: String(row.field),
      category: String(row.category),
      looksFor: String(row.looks_for),
      // The column is nullable, and only a Symbol Rule ever carries it.
      flanked: row.flanked === null || row.flanked === undefined ? null : String(row.flanked),
      reason: String(row.reason),
      exceptions: exceptions.get(Number(row.id)) ?? [],
    }))
  }

  async listDocuments(): Promise<ListedReferenceDocument[]> {
    const rows = await this.queries.run('select id, title from reference_documents order by id')

    return rows.map((row) => ({ id: String(row.id), title: String(row.title) }))
  }

  async getDocument(id: string): Promise<ReferenceDocument | undefined> {
    const [row] = await this.queries.run(
      'select title, body from reference_documents where id = $1',
      [id],
    )

    return row === undefined ? undefined : { title: String(row.title), body: String(row.body) }
  }
}

/** What this project needs of a connected client, which is one method of it. */
interface Connected {
  query(sql: string, parameters?: unknown[]): Promise<{ rows: unknown[] }>
}

/**
 * Puts a connected client behind the statements-and-rows seam everything above
 * speaks in. Exported so that a test running an in-process Postgres reaches it
 * through this same adapter rather than through a copy of it.
 */
export function queriesFrom(client: Connected): Queries {
  return {
    async run(sql: string, parameters?: unknown[]) {
      const { rows } = await client.query(sql, parameters)
      return rows as Record<string, unknown>[]
    },
  }
}

/**
 * Opens the one connection this process needs. Narrow by design: everything
 * above it speaks in statements and rows, so the store is exercised without a
 * database and this is the only part that needs one.
 */
export async function connectToPostgres(url: string): Promise<Queries & { close(): Promise<void> }> {
  const client = new pg.Client({ connectionString: url })

  await client.connect()

  return { ...queriesFrom(client), close: () => client.end() }
}

import { spawn, type ChildProcess } from 'node:child_process'
import { fileURLToPath } from 'node:url'

import { afterAll, beforeAll, describe, expect, it } from 'vitest'

import { expectedTestLinkMcp } from '../src/mcp-testlink-client.js'

/**
 * What this proves: a Test Case submitted through the running server lands in a
 * real TestLink, and the id the write answers with is the id a read of that
 * TestLink answers to.
 *
 * It is the one thing the rest of the suite cannot say. Every other file here
 * substitutes TestLink — `stub-testlink-client.ts` — or Postgres — `pg-mem` —
 * and none of them imports `src/server.ts` at all, so an id invented in the
 * answer and never stored would pass all of them. This file starts the real
 * entry point the way `npm run dev` does, and every hop below it is the real
 * one: the real testlink-mcp container, the real TestLink, the real database.
 *
 * Nothing is substituted. One thing is configured rather than defaulted, and it
 * is named here because it is the seam that would otherwise be silent:
 * `src/server.ts` launches testlink-mcp in a container with no `--network`
 * flag, which cannot reach a TestLink published on the host's own localhost —
 * the address `.env.example` documents and `.mcp.json` uses. So the launch is
 * overridden with the host-network form `.mcp.json` already carries, through
 * the two settings the server reads for exactly this purpose. The version is
 * imported from the client rather than restated, so it cannot drift from the
 * testlink-mcp the client is written against. Set TESTLINK_MCP_COMMAND and
 * TESTLINK_MCP_ARGS in the environment to launch it some other way.
 *
 * What it needs, none of which it creates for itself:
 *
 *   docker compose up -d
 *   psql "$DATABASE_URL" -f schema.sql
 *   psql "$DATABASE_URL" -f default-rules.sql
 *
 * and a `.env` naming that database, that TestLink and an API key for it. With
 * any of them absent this file fails rather than skips: it exists to be the
 * check that cannot pass while the real path is broken.
 */

/** Where this run's server listens. Not 3000 or the .env PORT: a server already up is not this one. */
const port = Number(process.env.SYSTEM_TEST_PORT ?? 8131)
const server = `http://127.0.0.1:${port}`

const repository = fileURLToPath(new URL('..', import.meta.url))

/**
 * The fixture Project and Test Suite this write is placed in, and the Test Case
 * it writes. Stable names, never suffixed: a run that dies before its teardown
 * leaves them findable, so the next run reuses what it finds instead of filling
 * TestLink with near-duplicates. The prefix is stamped into the Project forever
 * and TestLink will not have two, which is another reason not to generate one.
 */
const fixture = {
  project: { name: 'Validator System Test', prefix: 'VSTX' },
  suite: { name: 'Write and read back' },
  /**
   * Wording chosen to violate none of the shipped Rules — no colon, no hyphen,
   * none of the terms in `default-rules.sql` — because a Rejection is a 422 and
   * this file is not about what the Rules do. If the Rules grow to catch this,
   * the failure says so: the body of a 422 names the Rule that fired.
   */
  testCase: {
    name: 'Guest device joins the open SSID',
    summary: 'A guest device associates with the open SSID and loads the portal page.',
    preconditions: 'The open SSID is broadcast on the access point.',
  },
}

/** What the server answered, kept whole so a failure can quote it. */
interface Answer {
  status: number
  text: string
  body: any
}

async function call(method: string, path: string, payload?: unknown): Promise<Answer> {
  const response = await fetch(`${server}${path}`, {
    method,
    ...(payload === undefined
      ? {}
      : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }),
  })
  const text = await response.text()

  return { status: response.status, text, body: text === '' ? undefined : JSON.parse(text) }
}

/**
 * The answer, or a failure naming what was asked and what came back. Written as
 * a throw rather than an expectation so the same reading works in a hook: a
 * TestLink that is not answering has to say so where it happened, not as an
 * undefined further down.
 */
function answered(what: string, answer: Answer, status: number): Answer {
  if (answer.status !== status) {
    throw new Error(`${what} answered ${answer.status} rather than ${status}: ${answer.text}`)
  }

  return answer
}

/**
 * A listing, reading a Project or a Test Suite that holds nothing yet as the
 * empty listing it is.
 *
 * TestLink reports "is empty" as an API failure rather than as an empty result,
 * and `McpTestLinkClient` matches only "does not exist" and "not found", so that
 * wording escalates as an outage and the server answers 500. That is worth an
 * issue of its own and it is not what this file is about: it shows up only on
 * the way to placing the fixture, on the first run against a TestLink that has
 * never held it. Read here, in the fixture path alone — every answer the claim
 * itself reads is demanded outright.
 */
function listed(what: string, answer: Answer): { id: string; name: string }[] {
  if (answer.status === 500 && /is empty/i.test(answer.text)) {
    return []
  }

  return answered(what, answer, 200).body as { id: string; name: string }[]
}

let serverProcess: ChildProcess
/** Everything the server said, so a start that never completes reports its own reason. */
let said = ''
let projectId: string
let suiteId: string
let writtenId: string | undefined

/** The real entry point, launched the way `npm run dev` launches it. */
async function startServer(): Promise<void> {
  serverProcess = spawn('npx', ['tsx', '--env-file-if-exists=.env', 'src/server.ts'], {
    cwd: repository,
    // Set here rather than in .env: what is set in the environment wins over the
    // file, so this names the port and the launch without editing anything.
    env: {
      ...process.env,
      PORT: String(port),
      TESTLINK_MCP_COMMAND: process.env.TESTLINK_MCP_COMMAND ?? 'docker',
      TESTLINK_MCP_ARGS:
        process.env.TESTLINK_MCP_ARGS ??
        JSON.stringify([
          'run',
          '--rm',
          '-i',
          '--network',
          'host',
          '-e',
          'TESTLINK_URL',
          '-e',
          'TESTLINK_API_KEY',
          `dogkeeper886/testlink-mcp:${expectedTestLinkMcp}`,
        ]),
    },
    // Its own group, so stopping it stops the testlink-mcp it spawned as well.
    detached: true,
    stdio: ['ignore', 'pipe', 'pipe'],
  })

  serverProcess.stdout?.on('data', (chunk) => (said += chunk))
  serverProcess.stderr?.on('data', (chunk) => (said += chunk))

  // Readiness is asked of the route that reads only the database, so a TestLink
  // that is down is reported by the step that needed it rather than as a server
  // that never started.
  for (let attempt = 0; attempt < 120; attempt++) {
    if (serverProcess.exitCode !== null) {
      throw new Error(`The server exited with ${serverProcess.exitCode} before it listened: ${said}`)
    }

    try {
      await call('GET', '/reference-documents')
      return
    } catch {
      await new Promise((wait) => setTimeout(wait, 500))
    }
  }

  throw new Error(`The server did not listen on ${port}: ${said}`)
}

function stopServer(): void {
  if (serverProcess?.pid !== undefined && serverProcess.exitCode === null) {
    try {
      process.kill(-serverProcess.pid, 'SIGTERM')
    } catch {
      serverProcess.kill('SIGTERM')
    }
  }
}

/** The fixture Project, reused where TestLink already holds one under this name. */
async function placeProject(): Promise<string> {
  const projects = answered('Listing the Projects', await call('GET', '/projects'), 200)
  const held = (projects.body as { id: string; name: string }[]).find(
    (project) => project.name === fixture.project.name,
  )

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Project ${fixture.project.name}`,
    await call('POST', '/projects', {
      ...fixture.project,
      notes: 'Fixture Project for the system test that writes a Test Case and reads it back.',
    }),
    201,
  )

  return String(created.body.id)
}

/** The fixture Test Suite under it, reused the same way and for the same reason. */
async function placeSuite(): Promise<string> {
  const held = listed(
    `Listing the Test Suites of Project ${projectId}`,
    await call('GET', `/projects/${projectId}/suites`),
  ).find((suite) => suite.name === fixture.suite.name)

  if (held !== undefined) {
    return String(held.id)
  }

  const created = answered(
    `Creating Test Suite ${fixture.suite.name}`,
    await call('POST', `/projects/${projectId}/suites`, {
      ...fixture.suite,
      details: 'Fixture Test Suite for the system test that writes a Test Case and reads it back.',
    }),
    201,
  )

  return String(created.body.id)
}

/**
 * A Test Case this fixture name is already on, from a run that failed before its
 * teardown. Removed rather than written beside, so the write below is the only
 * one under that name and a leak cannot accumulate.
 */
async function removeLeftovers(): Promise<void> {
  const cases = listed(
    `Listing the Test Cases in Test Suite ${suiteId}`,
    await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
  )

  for (const held of cases) {
    if (held.name === fixture.testCase.name) {
      answered(
        `Removing the leftover Test Case ${held.id}`,
        await call('DELETE', `/test-cases/${held.id}`),
        204,
      )
    }
  }
}

describe('a Test Case written through the running server', () => {
  beforeAll(async () => {
    await startServer()
    projectId = await placeProject()
    suiteId = await placeSuite()
    await removeLeftovers()
  }, 120_000)

  afterAll(async () => {
    try {
      if (writtenId !== undefined) {
        answered(
          `Removing the Test Case ${writtenId} this run created`,
          await call('DELETE', `/test-cases/${writtenId}`),
          204,
        )

        // Verified rather than assumed: TestLink can report the removal, so the
        // next run starts from a TestLink this one left as it found it.
        answered(
          `Reading the removed Test Case ${writtenId}`,
          await call('GET', `/test-cases/${writtenId}`),
          404,
        )
      }
    } finally {
      stopServer()
    }
  }, 60_000)

  it('lands in TestLink under the id the write answered with', async () => {
    const written = answered(
      'The submission',
      await call('POST', `/projects/${projectId}/suites/${suiteId}/test-cases`, fixture.testCase),
      201,
    )

    writtenId = String(written.body.id)
    expect(writtenId).not.toBe('')

    // The id is TestLink's own, not one this answer minted: TestLink's tree
    // reports the Test Case under it, with the Fields that were sent.
    const inSuite = answered(
      `Listing the Test Cases in Test Suite ${suiteId}`,
      await call('GET', `/projects/${projectId}/suites/${suiteId}/test-cases`),
      200,
    )
    expect((inSuite.body as { id: string }[]).map((held) => String(held.id))).toContain(writtenId)

    // And the read the API serves answers to that same id, with what was
    // written rather than with what the write was told.
    const read = answered(
      `Reading Test Case ${writtenId} back`,
      await call('GET', `/test-cases/${writtenId}`),
      200,
    )
    expect(read.body.testCase).toEqual(fixture.testCase)
  }, 60_000)
})

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import type { StoredRule } from '../src/rule-set.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/** Rule Sets binding no Rules: this seam is about the HTTP surface. */
const noRules: StoredRule[] = []

/** Where the caller places the submission. TestLink is the store, so the caller says where. */
const placement = { projectId: '12', suiteId: '48' }

/** Exercises the HTTP surface with a stubbed TestLink client. */
async function submit(payload: Record<string, unknown>) {
  const testlink = new StubTestLinkClient()
  testlink.holdSuite(placement.suiteId)
  const app = buildApp({ documents: new StubDocumentStore(), testlink, rules: noRules })
  const response = await app.inject({
    method: 'POST',
    url: `/projects/${placement.projectId}/suites/${placement.suiteId}/test-cases`,
    payload,
  })

  return { testlink, response }
}

const wellFormed = {
  name: 'Guest joins the open SSID',
  summary: 'A guest device associates with the open SSID and reaches the portal.',
  preconditions: 'The open SSID is broadcast on the AP.',
}

describe('submitting a Test Case', () => {
  it('writes a well-formed Test Case through to TestLink', async () => {
    const { testlink, response } = await submit(wellFormed)

    expect(response.statusCode).toBe(201)
    expect(response.json()).toEqual({
      id: 'testlink-1',
      ruleSetVersion: response.headers['rule-set-version'],
    })
    expect(testlink.written).toEqual([{ placement, testCase: wellFormed }])
  })

  it('refuses a submission missing a required Field before it reaches TestLink', async () => {
    const { testlink, response } = await submit({ name: wellFormed.name })

    expect(response.statusCode).toBe(400)
    expect(response.json().message).toContain('summary')
    expect(testlink.written).toEqual([])
  })

  it('refuses a submission carrying a Field of the wrong type', async () => {
    const { testlink, response } = await submit({ name: wellFormed.name, summary: 42 })

    expect(response.statusCode).toBe(400)
    expect(response.json().message).toContain('summary')
    expect(testlink.written).toEqual([])
  })

  it('refuses by schema in a shape a Rejection could not be confused with', async () => {
    const { response } = await submit({ name: wellFormed.name })

    const body = response.json()
    expect(body.refusal).toBe('schema')
    expect(body).not.toHaveProperty('violations')
  })

  // A Suite that is not there is the caller's to correct, so it answers as a
  // client error — where TestLink being unreachable answers as a server one.
  it('answers a write into a Test Suite TestLink does not hold as a client error', async () => {
    const testlink = new StubTestLinkClient()
    const app = buildApp({ documents: new StubDocumentStore(), testlink, rules: noRules })

    const response = await app.inject({
      method: 'POST',
      url: '/projects/12/suites/999/test-cases',
      payload: wellFormed,
    })

    expect(response.statusCode).toBe(404)
    expect(response.json()).not.toHaveProperty('violations')
    expect(testlink.written).toEqual([])
  })

  it('answers a write attempted while TestLink is unreachable as a server error', async () => {
    const testlink = new StubTestLinkClient(false)
    const app = buildApp({ documents: new StubDocumentStore(), testlink, rules: noRules })

    const response = await app.inject({
      method: 'POST',
      url: '/projects/12/suites/48/test-cases',
      payload: wellFormed,
    })

    expect(response.statusCode).toBe(500)
    expect(response.json()).not.toHaveProperty('violations')
  })
})

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import { PostgresStore } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'
import { empty, shipped } from './shipped.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/** The schema the repository ships, which is the operator's first step. */
const schema = shipped('schema.sql')

/** The columns an operator names to write a Rule, in the order the values follow. */
const writeRule =
  'insert into rules (rule_id, content_kind, field, category, looks_for, flanked, reason) values ($1, $2, $3, $4, $5, $6, $7)'

/** One Rule, written the way an operator writes one. */
const noUtilise = [
  'no-utilise',
  'testCase',
  'summary',
  'term',
  'utilise',
  null,
  'The product documentation says use, not utilise.',
]

/**
 * A database an operator has written their Rules and Reference Documents into,
 * as a running server would find one. The writes are plain SQL because that is
 * now the whole of the write path: nothing this project ships puts a row in this
 * database.
 */
async function configured(): Promise<{ queries: Queries; store: PostgresStore }> {
  const queries = empty()

  await queries.run(schema)
  await queries.run(writeRule, noUtilise)
  await queries.run('insert into reference_documents (id, title, body) values ($1, $2, $3)', [
    'roaming',
    'Roaming between APs',
    'The client reconnects.',
  ])
  await queries.run('insert into reference_documents (id, title, body) values ($1, $2, $3)', [
    'ssid',
    'SSID naming',
    'Name it well.',
  ])

  return { queries, store: new PostgresStore(queries) }
}

describe('the schema the repository ships', () => {
  it('is a schema Postgres accepts, and makes every table the server reads', async () => {
    const queries = empty()

    await expect(queries.run(schema)).resolves.toBeDefined()
    await expect(queries.run('select rule_id from rules')).resolves.toEqual([])
    await expect(queries.run('select rule, phrase from rule_exceptions')).resolves.toEqual([])
    await expect(queries.run('select id, title, body from reference_documents')).resolves.toEqual([])
  })

  // Applying it twice is safe by construction — every statement is `if not
  // exists` — but that is not asserted here: the in-process Postgres refuses to
  // re-parse the second apply, so a test of it would be a test of pg-mem's
  // limits rather than of the schema.
})

/**
 * A Rule is a row, and the schema is what refuses a malformed one — while the
 * operator is present to fix it, rather than at the next startup. The binder
 * reports these too, and `load-rule-sets.test.ts` exercises that; this is the
 * gate in front of it, which is the one an operator actually meets.
 */
describe('what the schema refuses an operator writing a Rule', () => {
  /** Whether the database took the row, so a refusal is told from an acceptance. */
  async function accepts(values: unknown[]): Promise<boolean> {
    const queries = empty()

    await queries.run(schema)

    try {
      await queries.run(writeRule, values)
      return true
    } catch {
      return false
    }
  }

  it('takes a Rule with nothing wrong with it', async () => {
    expect(await accepts(noUtilise)).toBe(true)
  })

  it('refuses a Field the content does not have', async () => {
    expect(await accepts(['no-utilise', 'testCase', 'title', 'term', 'utilise', null, 'r'])).toBe(
      false,
    )
  })

  it('refuses content that is neither a Test Case nor a Reference Document', async () => {
    expect(await accepts(['no-utilise', 'testcase', 'summary', 'term', 'utilise', null, 'r'])).toBe(
      false,
    )
  })

  it('refuses a kind of check the server has no way to run', async () => {
    expect(await accepts(['no-label', 'testCase', 'summary', 'regex', '^Summary:', null, 'r'])).toBe(
      false,
    )
  })

  it('refuses a Symbol Rule looking for more than a single character', async () => {
    expect(await accepts(['no-ellipsis', 'testCase', 'summary', 'symbol', '...', null, 'r'])).toBe(
      false,
    )
  })

  // One character rather than one byte, which is the same reading the server
  // makes: a Symbol Rule is written for a mark, not for its encoding.
  it('takes a Symbol Rule looking for one character outside ASCII', async () => {
    expect(await accepts(['no-em-dash', 'testCase', 'summary', 'symbol', '—', null, 'r'])).toBe(true)
  })

  it('refuses flanking on a Term Rule, which is looked for as a word already', async () => {
    expect(
      await accepts(['no-utilise', 'testCase', 'summary', 'term', 'utilise', 'whitespace', 'r']),
    ).toBe(false)
  })

  it('refuses flanking by a condition that does not exist', async () => {
    expect(await accepts(['no-dash', 'testCase', 'summary', 'symbol', '-', 'spaces', 'r'])).toBe(
      false,
    )
  })

  it('refuses a Rule carrying no reason to return to the caller', async () => {
    expect(await accepts(['no-utilise', 'testCase', 'summary', 'term', 'utilise', null, ''])).toBe(
      false,
    )
  })

  // Unique per Field rather than overall: the same id on two Fields is two
  // Rules, and both are worth having.
  it('refuses a second Rule under an id already taken on that Field', async () => {
    const queries = empty()

    await queries.run(schema)
    await queries.run(writeRule, noUtilise)

    await expect(queries.run(writeRule, noUtilise)).rejects.toThrow()
  })

  it('takes the same id on another Field, which is another Rule', async () => {
    const queries = empty()

    await queries.run(schema)
    await queries.run(writeRule, noUtilise)

    await expect(
      queries.run(writeRule, ['no-utilise', 'testCase', 'name', 'term', 'utilise', null, 'r']),
    ).resolves.toBeDefined()
  })
})

describe('what an operator puts in reach of the server', () => {
  it('hands back a Rule in the shape the binder takes', async () => {
    expect(await (await configured()).store.rules()).toEqual([
      {
        ruleId: 'no-utilise',
        contentKind: 'testCase',
        field: 'summary',
        category: 'term',
        looksFor: 'utilise',
        flanked: null,
        reason: 'The product documentation says use, not utilise.',
        exceptions: [],
      },
    ])
  })

  it('hands back an Exception on the Rule it was written against', async () => {
    const { queries, store } = await configured()

    await queries.run(
      "insert into rule_exceptions (rule, phrase) select id, 'utilise the CLI' from rules where rule_id = 'no-utilise'",
    )

    expect((await store.rules()).map(({ exceptions }) => exceptions)).toEqual([['utilise the CLI']])
  })

  it('serves every document that was written', async () => {
    expect(await (await configured()).store.listDocuments()).toEqual([
      { id: 'roaming', title: 'Roaming between APs' },
      { id: 'ssid', title: 'SSID naming' },
    ])
  })

  it('serves a document whole, under the id it was written under', async () => {
    expect(await (await configured()).store.getDocument('roaming')).toEqual({
      title: 'Roaming between APs',
      body: 'The client reconnects.',
    })
  })

  it('answers nothing for an id the database holds no document under', async () => {
    expect(await (await configured()).store.getDocument('absent')).toBeUndefined()
  })

  // A database holding Rules and nothing to serve is not the same as one that
  // has never been set up — the server tells those apart to decide whether to
  // start at all.
  it('serves nothing where no documents were written, having Rules all the same', async () => {
    const queries = empty()

    await queries.run(schema)
    await queries.run(writeRule, noUtilise)

    expect(await new PostgresStore(queries).listDocuments()).toEqual([])
    expect(await new PostgresStore(queries).rules()).toHaveLength(1)
  })

  // A database with no tables in it at all — the schema never applied, not
  // merely empty. It answers "none" rather than failing on a table that is not
  // there, which is what lets the server say what to do instead of dying on a
  // missing relation.
  it('answers no Rules where the schema has never been applied', async () => {
    expect(await new PostgresStore(empty()).rules()).toEqual([])
  })

  // The schema is applied but nothing has been written into it. Still "none",
  // and still not an outage.
  it('answers no Rules where none have been written', async () => {
    const queries = empty()

    await queries.run(schema)

    expect(await new PostgresStore(queries).rules()).toEqual([])
  })
})

/**
 * A Rule that should stop firing is switched off rather than deleted (ADR-0007).
 * It has to stop firing just as completely, and its row has to stay, or a
 * Violation already logged against it can no longer be explained.
 */
describe('switching a Rule off', () => {
  async function withSecondRule() {
    const { queries, store } = await configured()

    await queries.run(writeRule, [
      'no-leverage',
      'testCase',
      'summary',
      'term',
      'leverage',
      null,
      'The product documentation says use, not leverage.',
    ])

    return { queries, store }
  }

  it('takes it out of what the server reads, leaving the others', async () => {
    const { queries, store } = await withSecondRule()

    await queries.run("update rules set enabled = false where rule_id = 'no-utilise'")

    expect((await store.rules()).map(({ ruleId }) => ruleId)).toEqual(['no-leverage'])
  })

  it('leaves the row where it was written, so what it judged stays explainable', async () => {
    const { queries } = await withSecondRule()

    await queries.run("update rules set enabled = false where rule_id = 'no-utilise'")

    const rows = await queries.run('select rule_id, enabled from rules order by id')

    expect(rows).toEqual([
      { rule_id: 'no-utilise', enabled: false },
      { rule_id: 'no-leverage', enabled: true },
    ])
  })

  it('takes a disabled Exception out too, leaving its Rule firing', async () => {
    const { queries, store } = await configured()

    await queries.run(
      "insert into rule_exceptions (rule, phrase, enabled) select id, 'utilise the CLI', false from rules where rule_id = 'no-utilise'",
    )

    expect(await store.rules()).toEqual([
      expect.objectContaining({ ruleId: 'no-utilise', exceptions: [] }),
    ])
  })
})

/**
 * The whole chain, from the SQL an operator writes to what a caller reads back
 * over HTTP. Every other test here stops at one seam; this one crosses all of
 * them, so a mistake in the wiring between them has somewhere to show up.
 *
 * The statements are the ones the README documents, extracted rather than
 * restated. ADR-0006 answers ADR-0005's objection to writing Rules out of band
 * by pointing at documented SQL — so this fails if that documentation drifts
 * into statements a Postgres will not run, or writes something the server then
 * cannot read.
 *
 * It runs every ```sql block in the README, in order, as one setup. That is the
 * point — the README is a sequence an operator follows top to bottom — but it
 * means a block added there joins this fixture, and the expectations below are
 * pinned to what those blocks write: the id `roaming`, its title, and a document
 * breaking none of the Rules the same README writes. A block that changes any of
 * those fails here, which is the reminder to update both together. Statements
 * shown for reference rather than to be run are fenced without a language, and
 * so are left out.
 */
describe('from the SQL an operator writes to what a caller reads', () => {
  /** Every ```sql block in the README, in the order it documents them. */
  function documentedSql(): string[] {
    return [...shipped('README.md').matchAll(/```sql\n([\s\S]*?)```/g)].map(([, sql]) => sql)
  }

  async function running() {
    const queries = empty()

    await queries.run(schema)

    for (const sql of documentedSql()) {
      await queries.run(sql)
    }

    const store = new PostgresStore(queries)

    // A Suite to write into, so a submission the Rules pass reaches a write
    // rather than stopping at a TestLink holding nothing.
    const testlink = new StubTestLinkClient()
    testlink.holdSuite('48')

    return buildApp({
      testlink,
      documents: store,
      // Exactly what the server does at startup: bind what the database holds.
      rules: await store.rules(),
    })
  }

  it('serves what was written, under the id it was written under', async () => {
    const app = await running()

    const listed = await app.inject({ method: 'GET', url: '/reference-documents' })

    expect(listed.statusCode).toBe(200)
    expect(listed.json()).toEqual([{ id: 'roaming', title: 'Roaming between access points' }])
  })

  it('retrieves a document by the id the listing gave, and nothing else', async () => {
    const app = await running()

    const [{ id }] = (await app.inject({ method: 'GET', url: '/reference-documents' })).json() as {
      id: string
    }[]
    const retrieved = await app.inject({ method: 'GET', url: `/reference-documents/${id}` })

    expect(retrieved.statusCode).toBe(200)
    expect(retrieved.json().document.title).toBe('Roaming between access points')
  })

  it('runs the Rules that were written beside it, finding nothing in the documented example', async () => {
    const app = await running()

    const response = await app.inject({ method: 'GET', url: '/reference-documents/roaming' })

    expect(response.json().violations).toEqual([])
    expect(response.json().ruleSetVersion).toEqual(expect.any(String))
  })

  // The Rules that reached the server came out of the database, so this fails if
  // what was written is not what is being enforced.
  it('rejects a Test Case under the Rules that were written, not under none', async () => {
    const app = await running()

    const response = await app.inject({
      method: 'POST',
      url: '/projects/12/suites/48/test-cases',
      payload: { name: 'Verify that the client roams', summary: 'The client reconnects.' },
    })

    expect(response.statusCode).toBe(422)
    expect(response.json().violations).toEqual([
      expect.objectContaining({ field: 'name', rule: 'no-verify-that' }),
    ])
  })

  // The Exception the README documents is attached by looking its Rule up, which
  // is the only way an operator can: the id is a serial nobody typed.
  it('suppresses the Rule the documented Exception was written against', async () => {
    const app = await running()

    const response = await app.inject({
      method: 'POST',
      url: '/projects/12/suites/48/test-cases',
      payload: {
        name: 'Client roams',
        summary: 'The client reconnects.',
        preconditions: 'AP isolation is enabled.',
      },
    })

    expect(response.statusCode).toBe(201)
  })
})

import { describe, expect, it } from 'vitest'

import { PostgresStore } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'

/**
 * Substitutes for the database, recording what was asked of it and answering
 * with rows a test supplies. The seam exists so the store — the statements it
 * runs, what it sends as a parameter, and how it reads what comes back — is
 * exercised without a database to connect to.
 */
class StubQueries implements Queries {
  readonly asked: { sql: string; parameters?: unknown[] }[] = []

  constructor(
    private readonly answer:
      | Record<string, unknown>[]
      | ((sql: string) => Record<string, unknown>[]) = [],
  ) {}

  async run(sql: string, parameters?: unknown[]): Promise<Record<string, unknown>[]> {
    this.asked.push({ sql, parameters })
    return typeof this.answer === 'function' ? this.answer(sql) : this.answer
  }
}

/**
 * A database with the schema applied, answering each of the statements the store
 * runs at startup with rows of its own. Reading the Rules takes more than one
 * statement, so answering them all alike would tell nothing apart.
 */
function holding(
  rules: Record<string, unknown>[],
  exceptions: Record<string, unknown>[] = [],
): StubQueries {
  return new StubQueries((sql) => {
    if (sql.includes('information_schema.tables')) {
      return [{ exists: 1 }]
    }

    return sql.includes('rule_exceptions') ? exceptions : rules
  })
}

/** One row of `rules`, as the database answers with one. */
const row = {
  id: 1,
  rule_id: 'no-utilise',
  content_kind: 'testCase',
  field: 'summary',
  category: 'term',
  looks_for: 'utilise',
  flanked: null,
  reason: 'The product documentation says use, not utilise.',
}

describe('reading the Rules at startup', () => {
  it('answers a Rule in the shape the binder above it takes', async () => {
    expect(await new PostgresStore(holding([row])).rules()).toEqual([
      {
        ruleId: 'no-utilise',
        contentKind: 'testCase',
        field: 'summary',
        category: 'term',
        looksFor: 'utilise',
        flanked: null,
        reason: 'The product documentation says use, not utilise.',
        exceptions: [],
      },
    ])
  })

  // An Exception belongs to exactly one Rule, so it has to arrive on that Rule
  // and on no other — a Rule wearing another's Exception would stop firing where
  // it should.
  it('attaches each Exception to the Rule it belongs to, and to no other', async () => {
    const queries = holding(
      [row, { ...row, id: 2, field: 'name' }],
      [
        { rule: 1, phrase: 'utilise the CLI' },
        { rule: 1, phrase: 'utilise the API' },
        { rule: 2, phrase: 'utilise the GUI' },
      ],
    )

    const rules = await new PostgresStore(queries).rules()

    expect(rules.map(({ field, exceptions }) => ({ field, exceptions }))).toEqual([
      { field: 'summary', exceptions: ['utilise the CLI', 'utilise the API'] },
      { field: 'name', exceptions: ['utilise the GUI'] },
    ])
  })

  // A disabled Rule judges nothing, so it is never read. Asked of the database
  // rather than filtered here: a row that never arrives cannot be bound by
  // mistake.
  it('asks the database for the enabled Rules and Exceptions, not for all of them', async () => {
    const queries = holding([row])

    await new PostgresStore(queries).rules()

    const [, rules, exceptions] = queries.asked

    expect(rules.sql).toContain('where enabled')
    expect(exceptions.sql).toContain('where enabled')
  })

  // Asked outright, rather than read out of the error a missing table raises: a
  // database the schema was never applied to is absence, not an outage, and the
  // two must not arrive as the same failure.
  it('asks whether the schema is there before reading a table that may not exist', async () => {
    const queries = holding([row])

    await new PostgresStore(queries).rules()

    expect(queries.asked[0].sql).toContain('information_schema.tables')
  })

  // Told apart from a Rule that fires on nothing, which is a server that checks
  // and finds nothing: this is a server with nothing to check with, and it
  // refuses to start.
  it('answers no Rules where none have been written at all', async () => {
    expect(await new PostgresStore(holding([])).rules()).toEqual([])
  })

  it('reads no further where the schema has never been applied', async () => {
    const queries = new StubQueries([])

    expect(await new PostgresStore(queries).rules()).toEqual([])
    expect(queries.asked).toHaveLength(1)
  })
})

