import { describe, expect, it } from 'vitest'

import { PostgresStore } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'
import { checkRules } from '../src/rule-set.js'
import { findViolations } from '../src/violation.js'
import { empty, shipped } from './shipped.js'

const schema = shipped('schema.sql')
const defaultRules = shipped('default-rules.sql')

/** A database an operator has taken both shipped steps against, in order. */
async function applied(): Promise<{ queries: Queries; store: PostgresStore }> {
  const queries = empty()

  await queries.run(schema)
  await queries.run(defaultRules)

  return { queries, store: new PostgresStore(queries) }
}

/** The five Fields the Rules reach, across both kinds of content. */
const everyField = [
  ['testCase', 'name'],
  ['testCase', 'summary'],
  ['testCase', 'preconditions'],
  ['referenceDocument', 'title'],
  ['referenceDocument', 'body'],
]

/** The Rule ids written against one Field, in a set so order says nothing. */
async function ruleIdsOn(queries: Queries, contentKind: string, field: string) {
  const rows = await queries.run(
    'select rule_id from rules where content_kind = $1 and field = $2',
    [contentKind, field],
  )

  return new Set(rows.map((row) => String(row.rule_id)))
}

describe('the default Rules the repository ships', () => {
  it('is SQL a Postgres accepts on top of the shipped schema', async () => {
    const { queries } = await applied()
    const [row] = await queries.run('select count(*)::int as written from rules')

    // 74 Terms and 15 Symbols, each bound to all five Fields.
    expect(row.written).toBe(445)
  })

  it('writes the same Rules against every Field, so no Field is left unchecked', async () => {
    const { queries } = await applied()
    const onName = await ruleIdsOn(queries, 'testCase', 'name')

    expect(onName.size).toBe(89)

    for (const [contentKind, field] of everyField) {
      expect(await ruleIdsOn(queries, contentKind, field)).toEqual(onName)
    }
  })

  it('arrives enabled, so applying it is the whole of the operator step', async () => {
    const { queries } = await applied()
    const [row] = await queries.run('select count(*)::int as off from rules where not enabled')

    expect(row.off).toBe(0)
  })

  it('binds every Rule it writes, so a server reading it starts', async () => {
    const { store } = await applied()
    const { bound, problems } = checkRules(await store.rules())

    expect(problems).toEqual([])
    expect([...bound.testCase.keys()].sort()).toEqual(['name', 'preconditions', 'summary'])
    expect([...bound.referenceDocument.keys()].sort()).toEqual(['body', 'title'])
  })

  it('is safe to apply again, and leaves a Rule the operator switched off switched off', async () => {
    const { queries } = await applied()

    await queries.run("update rules set enabled = false where rule_id = 'no-ensure-that'")
    await queries.run(defaultRules)

    const [row] = await queries.run('select count(*)::int as written from rules')
    const [tuned] = await queries.run(
      "select count(*)::int as off from rules where rule_id = 'no-ensure-that' and not enabled",
    )

    expect(row.written).toBe(445)
    // Re-applying must not undo the tuning, or the operator's only lever is one
    // a second `psql -f` silently pulls back.
    expect(tuned.off).toBe(5)
  })

  it('catches the tells it was written for', async () => {
    const { store } = await applied()
    const { bound } = checkRules(await store.rules())

    const violations = findViolations(
      {
        name: 'Verify that the system correctly handles various cases',
        summary: 'A comprehensive check that will leverage a robust setup — not just a smoke test.',
        preconditions: 'Moreover, the access point is configured properly ; the client is ready.',
      },
      bound.testCase,
    )

    const fired = (field: string) =>
      violations.filter((violation) => violation.field === field).map(({ rule }) => rule).sort()

    expect(fired('name')).toEqual(['no-correctly', 'no-various', 'no-verify-that'])
    expect(fired('summary')).toEqual([
      'no-comprehensive',
      'no-em-dash',
      'no-leverage',
      'no-not-just',
      'no-robust',
    ])
    expect(fired('preconditions')).toEqual([
      'no-moreover',
      'no-properly',
      'no-spaced-semicolon',
    ])
  })

  it('leaves a plainly written Test Case alone', async () => {
    const { store } = await applied()
    const { bound } = checkRules(await store.rules())

    const violations = findViolations(
      {
        name: 'Client rejoins the same SSID after the access point reboots',
        summary: 'The client is associated again within 30 seconds of the access point coming back up.',
        preconditions: 'One access point on firmware 6.1.2, and one client associated to SSID lab-a.',
      },
      bound.testCase,
    )

    expect(violations).toEqual([])
  })

  it('carries the Rule the README teaches the operator to write', async () => {
    const { store } = await applied()
    const rules = await store.rules()

    expect(
      rules.find((rule) => rule.ruleId === 'no-verify-that' && rule.field === 'name'),
    ).toMatchObject({ category: 'term', looksFor: 'verify that', flanked: null })
  })
})

import { describe, expect, it } from 'vitest'

import { McpTestLinkClient } from '../src/mcp-testlink-client.js'
import type { ToolCaller, ToolResult } from '../src/tool-caller.js'

/**
 * Substitutes for testlink-mcp, recording what was called and answering what
 * TestLink would. This seam exists because the real client cannot be exercised
 * at Seam 1 — the stub is what keeps Seam 1 free of a live TestLink, so the
 * tool names, the arguments and the reading of what comes back are covered
 * here instead, against the text testlink-mcp actually replies with.
 */
class FakeToolCaller implements ToolCaller {
  readonly calls: { tool: string; args: Record<string, unknown> }[] = []

  constructor(private readonly answers: Record<string, ToolResult>) {}

  async call(tool: string, args: Record<string, unknown>): Promise<ToolResult> {
    this.calls.push({ tool, args })

    const answer = this.answers[tool]
    if (answer === undefined) {
      throw new Error(`The test set up no answer for ${tool}.`)
    }

    return answer
  }
}

/** What testlink-mcp replies with when a tool worked: its result as JSON text. */
function reports(value: unknown): ToolResult {
  return { text: JSON.stringify(value, null, 2), isError: false }
}

/** What testlink-mcp replies with when a tool did not work. */
function fails(message: string): ToolResult {
  return { text: `Error: ${message}`, isError: true }
}

/** The message TestLink gives for an id it holds nothing under, as testlink-mcp passes it on. */
const absent = fails(
  'API call failed: TestLink API Error (5000): (getTestCase) - Test case ID (7777) does not exist!',
)

/**
 * What testlink-mcp says when it cannot reach TestLink at all, as observed from
 * a real testlink-mcp process pointed at a dead address. It is deliberately not
 * the tidier wording testlink-mcp's own source suggests: the connection error
 * arrives nested, so the phrasing that reaches a caller is this one. Nothing
 * here is matched for absence, which is the point — an outage this client has
 * never seen the wording of still escalates.
 */
const unreachable = fails('API call failed: Error: connect ECONNREFUSED 127.0.0.1:9')

/** A Test Case as TestLink answers a read: one version, in a list, with more Fields than we hold. */
const asTestLinkHoldsIt = [
  {
    testcase_id: '5074',
    name: 'Guest joins the open SSID',
    summary: 'A guest device associates with the open SSID.',
    preconditions: 'The open SSID is broadcast on the AP.',
    version: '1',
    importance: '2',
  },
]

const testCase = {
  name: 'Guest joins the open SSID',
  summary: 'A guest device associates with the open SSID.',
  preconditions: 'The open SSID is broadcast on the AP.',
}

const placement = { projectId: '12', suiteId: '48' }

function clientFor(answers: Record<string, ToolResult>) {
  const tools = new FakeToolCaller(answers)

  return { tools, client: new McpTestLinkClient(tools, { authorLogin: 'validator' }) }
}

describe('creating a Test Case through testlink-mcp', () => {
  // The author login is the one piece of TestLink identity the caller does not
  // supply: it is who the validator writes as, fixed at deployment.
  it('places the Test Case where the caller said, writing as the configured author', async () => {
    const { tools, client } = clientFor({
      create_test_case: reports([{ id: 5074, additionalInfo: { id: 5074, external_id: 12 } }]),
    })

    await client.createTestCase(placement, testCase)

    expect(tools.calls).toEqual([
      {
        tool: 'create_test_case',
        args: {
          data: {
            testprojectid: '12',
            testsuiteid: '48',
            name: 'Guest joins the open SSID',
            authorlogin: 'validator',
            summary: 'A guest device associates with the open SSID.',
            preconditions: 'The open SSID is broadcast on the AP.',
          },
        },
      },
    ])
  })

  it('leaves a Field the caller omitted out of the write rather than sending an empty one', async () => {
    const { tools, client } = clientFor({
      create_test_case: reports([{ id: 5074, additionalInfo: { id: 5074, external_id: 12 } }]),
    })

    await client.createTestCase(placement, { name: testCase.name, summary: testCase.summary })

    expect(tools.calls[0].args).toEqual({
      data: {
        testprojectid: '12',
        testsuiteid: '48',
        name: 'Guest joins the open SSID',
        authorlogin: 'validator',
        summary: 'A guest device associates with the open SSID.',
      },
    })
  })

  // The id TestLink gave, not one this client made up: it is the id a read is
  // then answered to, so a caller writes and reads back with the same string.
  it('answers the internal id TestLink gave the Test Case', async () => {
    const { client } = clientFor({
      create_test_case: reports([{ id: 5074, additionalInfo: { id: 5074, external_id: 12 } }]),
    })

    expect(await client.createTestCase(placement, testCase)).toEqual({ id: '5074' })
  })

  it('reads the id out of what TestLink reported about the write when it sends no top-level one', async () => {
    const { client } = clientFor({
      create_test_case: reports([{ additionalInfo: { id: 5074, external_id: 12 } }]),
    })

    expect(await client.createTestCase(placement, testCase)).toEqual({ id: '5074' })
  })

  // The write is reported complete on the id TestLink answered with, and on
  // nothing else: a reply carrying no id is a write that did not land, however
  // successfully it was phrased.
  it('refuses to report a write complete when TestLink confirmed no id', async () => {
    const { client } = clientFor({
      create_test_case: reports([{ status: false, message: 'Test case name already exists' }]),
    })

    await expect(client.createTestCase(placement, testCase)).rejects.toThrow(/TestLink/)
  })

  it('reports a Suite TestLink does not hold as absence, not as an outage', async () => {
    const { client } = clientFor({
      create_test_case: fails(
        'API call failed: TestLink API Error (7000): Test Suite (id: 999) does not exist!',
      ),
    })

    expect(await client.createTestCase(placement, testCase)).toBeUndefined()
  })

  it('reports TestLink being unreachable on a write as an outage', async () => {
    const { client } = clientFor({ create_test_case: unreachable })

    await expect(client.createTestCase(placement, testCase)).rejects.toThrow()
  })
})

describe('reading a Test Case through testlink-mcp', () => {
  it('asks for the Test Case by the id it was given', async () => {
    const { tools, client } = clientFor({ read_test_case: reports(asTestLinkHoldsIt) })

    await client.getTestCase('5074')

    expect(tools.calls).toEqual([{ tool: 'read_test_case', args: { test_case_id: '5074' } }])
  })

  // TestLink answers with every Field it holds; what comes back is the Fields
  // this project has Rules for, and nothing else, so a read serves a Test Case
  // rather than a TestLink record.
  it('answers the Fields of a Test Case, out of everything TestLink holds', async () => {
    const { client } = clientFor({ read_test_case: reports(asTestLinkHoldsIt) })

    expect(await client.getTestCase('5074')).toEqual(testCase)
  })

  it('answers a Test Case TestLink sends on its own rather than in a list', async () => {
    const { client } = clientFor({ read_test_case: reports(asTestLinkHoldsIt[0]) })

    expect(await client.getTestCase('5074')).toEqual(testCase)
  })

  it('answers a Field TestLink holds nothing in as empty rather than as missing', async () => {
    const { client } = clientFor({
      read_test_case: reports([{ name: 'Guest joins the open SSID', summary: null, preconditions: null }]),
    })

    expect(await client.getTestCase('5074')).toEqual({
      name: 'Guest joins the open SSID',
      summary: '',
      preconditions: '',
    })
  })

  it('reports an id TestLink holds nothing under as absence', async () => {
    const { client } = clientFor({ read_test_case: absent })

    expect(await client.getTestCase('7777')).toBeUndefined()
  })

  it('reports absence TestLink answers with rather than errors with, the same way', async () => {
    const { client } = clientFor({
      read_test_case: reports([{ code: 5000, message: '(getTestCase) - Test case ID (7777) does not exist!' }]),
    })

    expect(await client.getTestCase('7777')).toBeUndefined()
  })

  it('reports TestLink being unreachable as an outage, not as absence', async () => {
    const { client } = clientFor({ read_test_case: unreachable })

    await expect(client.getTestCase('5074')).rejects.toThrow()
  })

  // Absence is read out of a reported failure only. Anything this client cannot
  // place is an outage, because a caller told a Test Case is not there stops
  // looking for it — an unreadable failure must escalate, not be answered.
  it('reports a failure it cannot place as an outage, so nothing unplaced reads as absence', async () => {
    const { client } = clientFor({
      read_test_case: fails('API call failed: TestLink Authentication Failed: Invalid API key'),
    })

    await expect(client.getTestCase('5074')).rejects.toThrow()
  })

  // The words TestLink uses for absence are words a Test Case is entitled to
  // contain. Absence is read out of what TestLink reported about the call, never
  // out of the content it served, or a case about a missing file would vanish.
  it('serves content that talks about absence rather than reading it as absent', async () => {
    const talksAboutAbsence = {
      name: 'Config file is absent',
      summary: 'Verify the AP boots when /etc/wlan.conf does not exist.',
      preconditions: 'The file does not exist on the AP.',
    }
    const { client } = clientFor({ read_test_case: reports([talksAboutAbsence]) })

    expect(await client.getTestCase('5074')).toEqual(talksAboutAbsence)
  })

  it('reports a Test Case TestLink answers with no version of as absence', async () => {
    const { client } = clientFor({ read_test_case: reports([]) })

    expect(await client.getTestCase('7777')).toBeUndefined()
  })
})

describe('updating a Test Case through testlink-mcp', () => {
  it('applies the Fields to the Test Case named', async () => {
    const { tools, client } = clientFor({ update_test_case: reports([{ status: true }]) })

    expect(await client.updateTestCase('5074', testCase)).toBe(true)
    expect(tools.calls).toEqual([
      {
        tool: 'update_test_case',
        args: {
          test_case_id: '5074',
          data: {
            name: 'Guest joins the open SSID',
            summary: 'A guest device associates with the open SSID.',
            preconditions: 'The open SSID is broadcast on the AP.',
          },
        },
      },
    ])
  })

  it('reports an id TestLink holds nothing under as absence', async () => {
    const { client } = clientFor({ update_test_case: absent })

    expect(await client.updateTestCase('7777', testCase)).toBe(false)
  })

  // TestLink denies a write in a reply testlink-mcp passes on as a success, so
  // an update is answered on what TestLink said about it, not on the call
  // having returned. Reporting this one applied would report a write complete
  // that TestLink has just said did not happen.
  it('refuses to report an update applied that TestLink says did not happen', async () => {
    const { client } = clientFor({
      update_test_case: reports([{ status: false, message: 'Test case is not editable' }]),
    })

    await expect(client.updateTestCase('5074', testCase)).rejects.toThrow(/TestLink/)
  })

  it('reports TestLink being unreachable as an outage', async () => {
    const { client } = clientFor({ update_test_case: unreachable })

    await expect(client.updateTestCase('5074', testCase)).rejects.toThrow()
  })
})

describe('deleting a Test Case through testlink-mcp', () => {
  it('deletes the Test Case named', async () => {
    const { tools, client } = clientFor({ delete_test_case: reports([{ status: true }]) })

    expect(await client.deleteTestCase('5074')).toBe(true)
    expect(tools.calls).toEqual([{ tool: 'delete_test_case', args: { test_case_id: '5074' } }])
  })

  it('reports an id TestLink holds nothing under as absence', async () => {
    const { client } = clientFor({ delete_test_case: absent })

    expect(await client.deleteTestCase('7777')).toBe(false)
  })

  it('refuses to report a delete done that TestLink says did not happen', async () => {
    const { client } = clientFor({
      delete_test_case: reports([{ status: false, message: 'Test case has executions' }]),
