describe('Projects and Test Suites through testlink-mcp', () => {
  // No Rule binds to a Project or a Suite, so what TestLink reports is served
  // on as it reported it rather than reshaped into a model this project would
  // then have to keep in step with TestLink's.
  it('lists Projects as TestLink reports them', async () => {
    const projects = [{ id: '12', name: 'Wireless', prefix: 'WL' }]
    const { tools, client } = clientFor({ list_projects: reports(projects) })

    expect(await client.listProjects()).toEqual(projects)
    expect(tools.calls).toEqual([{ tool: 'list_projects', args: {} }])
  })

  it('creates a Project and answers the id TestLink gave it', async () => {
    const { tools, client } = clientFor({ create_project: reports([{ id: 12, status: true }]) })

    expect(await client.createProject({ name: 'Wireless', prefix: 'WL', notes: 'Guest flows' })).toEqual(
      { id: '12' },
    )
    expect(tools.calls).toEqual([
      {
        tool: 'create_project',
        args: { name: 'Wireless', prefix: 'WL', notes: 'Guest flows' },
      },
    ])
  })

  it('sends only the Project settings the caller named, so the rest keep TestLink’s defaults', async () => {
    const { tools, client } = clientFor({ create_project: reports([{ id: 12 }]) })

    await client.createProject({ name: 'Wireless', prefix: 'WL', requirementsEnabled: true })

    expect(tools.calls[0].args).toEqual({
      name: 'Wireless',
      prefix: 'WL',
      requirements_enabled: true,
    })
  })

  // `false` is a setting, not an omission: a caller turning a feature off has
  // said something, and dropping it would silently leave the feature on.
  it('sends a Project setting the caller turned off rather than dropping it', async () => {
    const { tools, client } = clientFor({ create_project: reports([{ id: 12 }]) })

    await client.createProject({ name: 'Wireless', prefix: 'WL', active: false, isPublic: false })

    expect(tools.calls[0].args).toEqual({
      name: 'Wireless',
      prefix: 'WL',
      active: false,
      is_public: false,
    })
  })

  // A testlink-mcp older than the one this client expects answers a tool it
  // does not have with `Unknown tool`, as observed from the image `:latest`
  // resolved to on a host that had pulled it before Project CRUD existed.
  // TestLink is reachable and healthy in that case and only the version is
  // wrong, so it must not read as an outage: someone told TestLink cannot be
  // reached goes looking at the server, which is not where the fault is.
  it('reports a tool the server does not provide as a version mismatch, naming the version expected', async () => {
    const { client } = clientFor({ create_project: fails('Unknown tool: create_project') })

    await expect(client.createProject({ name: 'Wireless', prefix: 'WL' })).rejects.toThrow(
      /create_project[\s\S]*1\.6\.0/,
    )
  })

  it('updates a Project by the id or prefix the caller named', async () => {
    const { tools, client } = clientFor({ update_project: reports([{ status: true }]) })

    expect(await client.updateProject('WL', { name: 'Wireless guest', notes: '' })).toBe(true)
    expect(tools.calls).toEqual([
      { tool: 'update_project', args: { project_id: 'WL', name: 'Wireless guest', notes: '' } },
    ])
  })

  // testlink-mcp reports a Project it cannot resolve in wording of its own,
  // which is neither of the phrasings TestLink itself uses. It still has to
  // reach a caller as absence, or an id they can correct reads as an outage.
  it('reports a Project TestLink does not hold as absence, however it is worded', async () => {
    const { client } = clientFor({ update_project: fails('Test project not found: 999') })

    expect(await client.updateProject('999', { name: 'Wireless' })).toBe(false)
  })

  it('deletes a Project once the caller has restated its prefix', async () => {
    const { tools, client } = clientFor({ delete_project: reports([{ status: true }]) })

    expect(await client.deleteProject('12', 'WL')).toBe('deleted')
    expect(tools.calls).toEqual([
      { tool: 'delete_project', args: { project_id: '12', confirm_prefix: 'WL' } },
    ])
  })

  // The interlock guards a delete that takes every Suite, Test Case and
  // Execution under the Project with it. Restating the prefix wrongly is the
  // caller's to correct, so it is answered apart from the Project not being
  // there and apart from TestLink not answering at all.
  it('tells a prefix restated wrongly apart from a Project that is not there', async () => {
    const { client } = clientFor({
      delete_project: fails(
        'Confirmation failed: confirm_prefix "XX" does not match the test case prefix "WL" of project "Wireless". Nothing was deleted.',
      ),
    })

    expect(await client.deleteProject('12', 'XX')).toBe('unconfirmed')
  })

  it('reports a delete of a Project TestLink does not hold as absence', async () => {
    const { client } = clientFor({ delete_project: fails('Test project not found: 999') })

    expect(await client.deleteProject('999', 'WL')).toBe('absent')
  })

  // The method behind an update ships in a TestLink fork. A server without it
  // is the operator's to fix, not the caller's, so it escalates rather than
  // being answered as a Project that is not there.
  it('reports a TestLink that cannot update Projects at all as an outage', async () => {
    const { client } = clientFor({
      update_project: fails(
        'This TestLink server does not provide tl.updateTestProject, which this tool requires.',
      ),
    })

    await expect(client.updateProject('12', { name: 'Wireless' })).rejects.toThrow()
  })

  it('lists the Test Suites of a Project', async () => {
    const { tools, client } = clientFor({ list_test_suites: reports([{ id: '48' }]) })

    expect(await client.listTestSuites('12')).toEqual([{ id: '48' }])
    expect(tools.calls).toEqual([{ tool: 'list_test_suites', args: { project_id: '12' } }])
  })

  // A listing of what is under something that is not there is the caller's id
  // to correct, so it is answered as absence rather than escalated as an outage.
  it('reports a listing under a Project TestLink does not hold as absence', async () => {
    const { client } = clientFor({
      list_test_suites: fails('API call failed: Test Project (id: 999) does not exist!'),
    })

    expect(await client.listTestSuites('999')).toBeUndefined()
  })

  it('reports a listing under a Test Suite TestLink does not hold as absence', async () => {
    const { client } = clientFor({
      list_test_cases_in_suite: fails('API call failed: Test Suite (id: 999) does not exist!'),
    })

    expect(await client.listTestCasesInSuite('999')).toBeUndefined()
  })

  it('lists the Test Suites under a parent Test Suite where one is named', async () => {
    const { tools, client } = clientFor({ list_test_suites: reports([{ id: '49' }]) })

    await client.listTestSuites('12', '48')

    expect(tools.calls[0].args).toEqual({ project_id: '12', parent_suite_id: '48' })
  })

  it('lists the Test Cases a Suite holds', async () => {
    const { tools, client } = clientFor({ list_test_cases_in_suite: reports([{ id: '5074' }]) })

    expect(await client.listTestCasesInSuite('48')).toEqual([{ id: '5074' }])
    expect(tools.calls).toEqual([{ tool: 'list_test_cases_in_suite', args: { suite_id: '48' } }])
  })

  it('creates a Test Suite and answers the id TestLink gave it', async () => {
    const { tools, client } = clientFor({ create_test_suite: reports([{ id: '48' }]) })

    expect(await client.createTestSuite('12', { name: 'Onboarding', details: 'Guest flows' })).toEqual({
      id: '48',
    })
    expect(tools.calls).toEqual([
      {
        tool: 'create_test_suite',
        args: { project_id: '12', suite_name: 'Onboarding', details: 'Guest flows' },
      },
    ])
  })

  it('creates a Test Suite under a parent Test Suite where one is named', async () => {
    const { tools, client } = clientFor({ create_test_suite: reports([{ id: '49' }]) })

    await client.createTestSuite('12', { name: 'Onboarding' }, '48')

    expect(tools.calls[0].args).toEqual({ project_id: '12', suite_name: 'Onboarding', parent_id: '48' })
  })

  it('reports a Project TestLink does not hold as absence', async () => {
    const { client } = clientFor({
      create_test_suite: fails('API call failed: Test Project (id: 999) does not exist!'),
    })

    expect(await client.createTestSuite('999', { name: 'Onboarding' })).toBeUndefined()
  })

  it('updates a Test Suite', async () => {
    const { tools, client } = clientFor({ update_test_suite: reports([{ status: true }]) })

    expect(await client.updateTestSuite('12', '48', { name: 'Guest onboarding' })).toBe(true)
    expect(tools.calls).toEqual([
      {
        tool: 'update_test_suite',
