    expect(await client.deleteTestSuite('48')).toBe(true)
    expect(tools.calls).toEqual([{ tool: 'delete_test_suite', args: { suite_id: '48' } }])
  })

  it('reports a Test Suite TestLink holds nothing under as absence', async () => {
    const { client } = clientFor({
      delete_test_suite: fails('API call failed: Test Suite (id: 999) does not exist!'),
    })

    expect(await client.deleteTestSuite('999')).toBe(false)
