})

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import type { TestCase } from '../src/testlink-client.js'
import { symbol, term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/**
 * The Rules the write path runs, bound to two Fields so a read reports across
 * a whole Test Case rather than one Field of it.
 */
const rules = [
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
  symbol({
    field: 'summary',
    id: 'no-spaced-dash',
    symbol: '-',
    flanked: 'whitespace',
    reason: 'A dash used as filler punctuation reads as unedited output.',
  }),
  symbol({
    field: 'preconditions',
    id: 'no-spaced-dash',
    symbol: '-',
    flanked: 'whitespace',
    reason: 'A dash used as filler punctuation reads as unedited output.',
  }),
]

/** Content the Rules fire on, as TestLink can hold it however it got there. */
const violating = {
  name: 'Guest joins the open SSID',
  summary: 'The device will utilise the open SSID - see the portal notes.',
  preconditions: 'Verify - the AP is broadcasting.',
}

/**
 * Content whose exact characters are the point: line breaks, leading and
 * trailing space, and text outside ASCII, all of which a read must hand back
 * as it found them.
 */
const awkward = {
  name: 'Gäste — SSID «offen»',
  summary: 'Line one.\nLine two will utilise the SSID.\n\n  Indented, and spaced.  ',
  preconditions: '日本語のテキスト - and an em dash — here.',
}

/** The same content with nothing for these Rules to fire on. */
const clean = {
  name: 'Guest joins the open SSID',
  summary: 'The device uses the open SSID and reaches the portal.',
  preconditions: 'The open SSID is broadcast on the AP.',
}

/** Exercises the HTTP surface with a stubbed TestLink client. */
async function read(testCase: TestCase) {
  const testlink = new StubTestLinkClient()
  testlink.hold('tc-1', testCase)
  const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })

  return app.inject({ method: 'GET', url: '/test-cases/tc-1' })
}

/** The write path, for reading the two paths against each other. */
async function submit(testCase: TestCase) {
  const testlink = new StubTestLinkClient()
  testlink.holdSuite('48')
  const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })

  return app.inject({
    method: 'POST',
    url: '/projects/12/suites/48/test-cases',
    payload: testCase,
  })
}

describe('reading a Test Case', () => {
  it('serves content the Rules fire on, whole and with a success status code', async () => {
    const response = await read(violating)

    expect(response.statusCode).toBe(200)
    expect(response.json().testCase).toEqual(violating)
  })

  it('attaches every Violation found in served content, as a Rejection carries them', async () => {
    const response = await read(violating)

    expect(response.json().violations).toEqual([
      {
        field: 'summary',
        rule: 'no-utilise',
        reason: 'The product documentation says use, not utilise.',
        text: 'utilise',
        offset: 16,
      },
      {
        field: 'summary',
        rule: 'no-spaced-dash',
        reason: 'A dash used as filler punctuation reads as unedited output.',
        text: '-',
        offset: 38,
      },
      {
        field: 'preconditions',
        rule: 'no-spaced-dash',
        reason: 'A dash used as filler punctuation reads as unedited output.',
        text: '-',
        offset: 7,
      },
    ])
  })

  it('serves a Test Case nothing fired on with an empty list, not an omitted Field', async () => {
    const response = await read(clean)

    expect(response.statusCode).toBe(200)
    expect(response.json().testCase).toEqual(clean)
    expect(response.json().violations).toEqual([])
  })

  it('hands back line breaks, spacing and text outside ASCII as it found them', async () => {
    const response = await read(awkward)

    expect(response.statusCode).toBe(200)
    expect(response.json().testCase).toEqual(awkward)
  })

  // The id is held, so only reachability is in question: an outage is reported
  // for a read that would otherwise have served content, not for one that had
  // nothing to serve anyway.
  it('answers a read of an unreachable TestLink as a server error, not a Rejection', async () => {
    const testlink = new StubTestLinkClient(false)
    testlink.hold('tc-1', violating)
    const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })

    const response = await app.inject({ method: 'GET', url: '/test-cases/tc-1' })

    expect(response.statusCode).toBe(500)
    expect(response.json()).not.toHaveProperty('violations')
  })

  // A client error, where the unreachable case above is a server one: the
  // caller corrects the id, rather than escalating an outage that is not
  // happening. The two status codes are what tells them apart.
  it('answers a read of an id TestLink does not hold as a client error, not a Rejection', async () => {
    const testlink = new StubTestLinkClient()
    const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })

    const response = await app.inject({ method: 'GET', url: '/test-cases/tc-9' })

    expect(response.statusCode).toBe(404)
    expect(response.json()).not.toHaveProperty('violations')
  })

  it('serves whole the content the write path refuses, reporting what that refusal did', async () => {
    const rejection = await submit(violating)
    const served = await read(violating)

    expect(rejection.statusCode).toBe(422)
    expect(served.statusCode).toBe(200)
    expect(served.json().testCase).toEqual(violating)
    expect(served.json().violations).toEqual(rejection.json().violations)
  })
})

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import type { TestCase } from '../src/testlink-client.js'
import { term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/** One Rule, which is enough to tell an update that is refused from one that lands. */
const rules = [
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
]

const clean = {
  name: 'Guest joins the open SSID',
  summary: 'The device uses the open SSID and reaches the portal.',
  preconditions: 'The open SSID is broadcast on the AP.',
}

const violating = {
  name: 'Guest joins the open SSID',
  summary: 'The device will utilise the open SSID.',
}

/** A TestLink holding one Test Case under `tc-1`, in a Suite a write can be placed in. */
function holding(testCase: TestCase = clean) {
  const testlink = new StubTestLinkClient()
  testlink.hold('tc-1', testCase)
  testlink.holdSuite('48')

  return { testlink, app: buildApp({ documents: new StubDocumentStore(), testlink, rules }) }
}

function update(app: ReturnType<typeof buildApp>, id: string, payload: Record<string, unknown>) {
  return app.inject({ method: 'PUT', url: `/test-cases/${id}`, payload })
}

describe('updating a Test Case', () => {
  it('applies a well-formed update to the Test Case TestLink holds', async () => {
    const { testlink, app } = holding()

    const response = await update(app, 'tc-1', clean)

    expect(response.statusCode).toBe(200)
    expect(testlink.updated).toEqual([{ id: 'tc-1', testCase: clean }])
  })

  // An update is a write, so the Rules run on it exactly as they run on a
  // submission: content the write path refuses is refused however it arrives.
  it('rejects an update producing a Violation, leaving what TestLink holds alone', async () => {
    const { testlink, app } = holding()

    const response = await update(app, 'tc-1', violating)

    expect(response.statusCode).toBe(422)
    expect(response.json().violations).toEqual([
      {
        field: 'summary',
        rule: 'no-utilise',
        reason: 'The product documentation says use, not utilise.',
        text: 'utilise',
        offset: 16,
      },
    ])
    expect(testlink.updated).toEqual([])
  })

  it('refuses an update missing a required Field before it reaches TestLink', async () => {
    const { testlink, app } = holding()

    const response = await update(app, 'tc-1', { name: clean.name })

    expect(response.statusCode).toBe(400)
    expect(response.json().refusal).toBe('schema')
    expect(testlink.updated).toEqual([])
  })

  // Creation and update are told apart by status code alone, so a caller knows
  // whether it added a Test Case or replaced one without reading the body.
  it('answers an update with a different status code from a creation', async () => {
    const { app } = holding()

    const created = await app.inject({
      method: 'POST',
      url: '/projects/12/suites/48/test-cases',
      payload: clean,
    })
    const updated = await update(app, 'tc-1', clean)

    expect(created.statusCode).toBe(201)
    expect(updated.statusCode).toBe(200)
  })

  it('answers an update of an id TestLink does not hold as a client error, not a Rejection', async () => {
    const { app } = holding()

    const response = await update(app, 'tc-9', clean)

    expect(response.statusCode).toBe(404)
    expect(response.json()).not.toHaveProperty('violations')
  })

  it('answers an update attempted while TestLink is unreachable as a server error', async () => {
    const testlink = new StubTestLinkClient(false)
    const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })

    const response = await update(app, 'tc-1', clean)

    expect(response.statusCode).toBe(500)
    expect(response.json()).not.toHaveProperty('violations')
  })
})

