import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import { symbol, term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/**
 * A Term Rule carrying an Exception, beside a Rule carrying none and the same
 * Term Rule bound to another Field without one, so a Rejection can be read for
 * the Rule the Exception belongs to and for the Rules it leaves alone. The
 * Symbol Rule carries an Exception too, because an Exception attaches to a Rule
 * rather than to a kind of Rule.
 */
const rules = [
  term({
    field: 'name',
    id: 'no-wireless-network',
    term: 'wireless network',
    reason: 'The product documentation says WLAN, not wireless network.',
  }),
  term({
    field: 'summary',
    id: 'no-wireless-network',
    term: 'wireless network',
    reason: 'The product documentation says WLAN, not wireless network.',
    exceptions: ['wireless network adapter'],
  }),
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
  symbol({
    field: 'summary',
    id: 'no-asterisk',
    symbol: '*',
    reason: 'An asterisk marks a footnote a Test Case does not carry.',
    exceptions: ['guest-*'],
  }),
]

/** Exercises the HTTP surface with a stubbed TestLink client. */
async function submit(testCase: Record<string, unknown>) {
  const testlink = new StubTestLinkClient()
  testlink.holdSuite('48')
  const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })
  const response = await app.inject({
    method: 'POST',
    url: '/projects/12/suites/48/test-cases',
    payload: testCase,
  })
  return { testlink, response }
}

describe('a Rule carrying an Exception', () => {
  it('produces no Violation where the Field matches the Exception', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client enables the wireless network adapter.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('produces a Violation where the Field does not match the Exception', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client joins the wireless network.',
    })

    expect(response.statusCode).toBe(422)
    expect(response.json().violations).toEqual([
      {
        field: 'summary',
        rule: 'no-wireless-network',
        reason: 'The product documentation says WLAN, not wireless network.',
        text: 'wireless network',
        offset: 21,
      },
    ])
  })

  it('fires where the Exception does not reach, in a Field where it does elsewhere', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The wireless network adapter fails and the wireless network drops.',
    })

    expect(response.json().violations).toEqual([
      expect.objectContaining({ rule: 'no-wireless-network', text: 'wireless network', offset: 43 }),
    ])
  })

  it('reads the Exception in any casing, as it reads a Term', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client enables the Wireless Network Adapter.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('reads the Exception however its words are spaced, as it reads a Term', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client enables the wireless\nnetwork adapter.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('suppresses a Symbol Rule the same way it suppresses a Term Rule', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client scans for guest-* and joins.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('suppresses the Rule where the Exception runs on into a longer word', async () => {
    const { testlink, response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client scans for guest-*1 and guest-*2.',
    })

    expect(response.statusCode).toBe(201)
    expect(testlink.written).toHaveLength(1)
  })

  it('leaves the Symbol Rule firing where the Exception does not match', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client scans for * and joins.',
    })

    expect(response.json().violations).toEqual([
      {
        field: 'summary',
        rule: 'no-asterisk',
        reason: 'An asterisk marks a footnote a Test Case does not carry.',
        text: '*',
        offset: 21,
      },
    ])
  })
})

describe('an Exception belonging to one Rule', () => {
  it('leaves another Rule on the same Field firing', async () => {
    const { response } = await submit({
      name: 'Guest joins the open SSID',
      summary: 'The client utilise the wireless network adapter.',
    })

    expect(response.json().violations).toEqual([
      expect.objectContaining({ field: 'summary', rule: 'no-utilise', offset: 11 }),
    ])
  })

  it('leaves the same Rule bound to another Field firing', async () => {
    const { response } = await submit({
      name: 'Client enables the wireless network adapter',
      summary: 'The client enables the wireless network adapter.',
    })

    expect(response.json().violations).toEqual([
      expect.objectContaining({ field: 'name', rule: 'no-wireless-network', offset: 19 }),
    ])
  })
})

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import type { StoredRule } from '../src/rule-set.js'
import { symbol, term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/** Exercises application startup with the Rules a database answered with. */
function start(rules: StoredRule[]) {
  return buildApp({
    testlink: new StubTestLinkClient(),
    documents: new StubDocumentStore(),
    rules,
  })
}

/** The problems an operator would read, one per line, stripped of their indent. */
function problemsReportedBy(rules: StoredRule[]): string[] {
  try {
    start(rules)
  } catch (error) {
    const [, ...problems] = (error as Error).message.split('\n')
    return problems.map((problem) => problem.trim())
  }

  throw new Error('The Rules were accepted, so there were no problems to report.')
}

/**
 * A row as the database holds one, for the tests below to break one column of.
 * Written out rather than built, because what is wrong with it is the subject.
 */
const valid: StoredRule = {
  ruleId: 'no-spaced-dash',
  contentKind: 'testCase',
  field: 'summary',
  category: 'symbol',
  looksFor: '-',
  flanked: 'whitespace',
  reason: 'A dash used as filler punctuation reads as unedited output.',
  exceptions: [],
}

/**
 * Every problem below is a CHECK constraint in `schema.sql` as well, which
 * refuses the row at insert while the operator is present to fix it — that is
 * where an operator meets it, and `database.test.ts` is where those are
 * exercised. This is the backstop underneath: a database those constraints were
 * never applied to must not produce a server that binds a Rule to a Field it was
 * not written for.
 */
describe('loading the Rules at startup', () => {
  it('starts when every Rule the database answered with is valid', () => {
    expect(() => start([valid])).not.toThrow()
  })

  it('starts when the database answered with no Rules for a Field', () => {
    expect(() => start([])).not.toThrow()
  })

  it('refuses to start when a Rule names a kind of check that does not exist', () => {
    expect(problemsReportedBy([{ ...valid, category: 'regex', looksFor: '^Summary:' }])).toEqual([
      'testCase / summary / no-spaced-dash: unknown rule type "regex"',
    ])
  })

  it('refuses to start when a Symbol Rule looks for more than a single character', () => {
    expect(problemsReportedBy([{ ...valid, looksFor: '...', flanked: null }])).toEqual([
      'testCase / summary / no-spaced-dash: symbol must be a single character, not "..."',
    ])
  })

  it('refuses to start when a Symbol Rule is flanked by a condition that does not exist', () => {
    expect(problemsReportedBy([{ ...valid, flanked: 'spaces' }])).toEqual([
      'testCase / summary / no-spaced-dash: flanked must be whitespace, not "spaces"',
    ])
  })

  it('refuses to start when a Term Rule looks for nothing', () => {
    expect(
      problemsReportedBy([
        { ...valid, ruleId: 'no-empty-term', category: 'term', looksFor: '', flanked: null },
      ]),
    ).toEqual(['testCase / summary / no-empty-term: term must be a word or phrase, not ""'])
  })

  // Flanking narrows where a character is looked for, and a Term is looked for
  // as a word already. A Term carrying it was stored as something other than
  // what it was written as.
  it('refuses to start when a Term Rule carries the flanking only a Symbol Rule takes', () => {
    expect(
      problemsReportedBy([{ ...valid, category: 'term', looksFor: 'utilise' }]),
    ).toEqual([
      'testCase / summary / no-spaced-dash: flanked belongs to a Symbol Rule, not a Term Rule',
    ])
  })
})

describe('a Rule that cannot be bound to a Field', () => {
  it('refuses to start when a Rule names a Field a Test Case does not have', () => {
    expect(problemsReportedBy([{ ...valid, field: 'sumary' }])).toEqual([
      'testCase / sumary / no-spaced-dash: a Test Case has no Field by that name',
    ])
  })

  // The Fields of the two do not overlap, so a Rule written under the wrong one
  // is refused rather than silently binding to nothing and never firing.
  it('refuses to start when a Rule names a Field a Reference Document does not have', () => {
    expect(problemsReportedBy([{ ...valid, contentKind: 'referenceDocument' }])).toEqual([
      'referenceDocument / summary / no-spaced-dash: a Reference Document has no Field by that name',
    ])
  })

  it('refuses to start when a Rule names content that has no Fields at all', () => {
    expect(problemsReportedBy([{ ...valid, contentKind: 'testcase' }])).toEqual([
      'testcase / summary / no-spaced-dash: Rules bind to a Test Case or a Reference Document, and this is neither',
    ])
  })
})

describe('a Rule that cannot be reported on', () => {
  it('refuses to start when a Rule has no id, saying so where the id would be', () => {
    expect(problemsReportedBy([{ ...valid, ruleId: '' }])).toEqual([
      'testCase / summary / a Rule with no id: id is missing',
    ])
  })

  it('refuses to start when a Rule carries no reason to return to the caller', () => {
    expect(problemsReportedBy([{ ...valid, reason: '' }])).toEqual([
      'testCase / summary / no-spaced-dash: reason is missing',
    ])
  })
})

/**
 * An unknown kind of check, two malformed ones, and one Rule with nothing wrong
 * with it — the case the acceptance criteria single out, where every problem has
 * to be reported rather than only the first. The last problem sits under a
 * Reference Document, so one pass reaches across both kinds of content rather
 * than stopping at the end of the Test Case.
 */
const fourProblems: StoredRule[] = [
  { ...valid, ruleId: 'no-restated-label', category: 'regex', looksFor: '^Summary:' },
  { ...valid, ruleId: 'no-ellipsis', looksFor: '...', flanked: null },
  {
    ...valid,
    ruleId: 'no-empty-term',
    field: 'preconditions',
    category: 'term',
    looksFor: '',
    flanked: null,
  },
  term({
    field: 'preconditions',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
  symbol({
    contentKind: 'referenceDocument',
    field: 'body',
    id: 'no-empty-symbol',
    symbol: '',
    reason: 'A Symbol Rule with no Symbol would fire on every Reference Document.',
  }),
]

describe('reporting an invalid Rule', () => {
  it('reports every problem in one pass, so they are fixed together', () => {
    const problems = problemsReportedBy(fourProblems).join('\n')

    expect(problems).toContain('no-restated-label')
    expect(problems).toContain('no-ellipsis')
    expect(problems).toContain('no-empty-term')
    expect(problems).toContain('no-empty-symbol')
  })

  it('leaves a Rule with nothing wrong with it out of the report', () => {
    expect(problemsReportedBy(fourProblems).join('\n')).not.toContain('no-utilise')
  })

  it('names the content, the Field and the Rule at fault in every problem it reports', () => {
    expect(problemsReportedBy(fourProblems)).toEqual([
      'testCase / summary / no-restated-label: unknown rule type "regex"',
      'testCase / summary / no-ellipsis: symbol must be a single character, not "..."',
      'testCase / preconditions / no-empty-term: term must be a word or phrase, not ""',
      'referenceDocument / body / no-empty-symbol: symbol must be a single character, not ""',
    ])
  })

  it('reads without a stack trace, because the message carries the whole report', () => {
    let message = ''

    try {
      start(fourProblems)
    } catch (error) {
      message = (error as Error).message
    }

    expect(message).toBe(
      [
        'Rule Sets are invalid, so the server will not start:',
        '  testCase / summary / no-restated-label: unknown rule type "regex"',
        '  testCase / summary / no-ellipsis: symbol must be a single character, not "..."',
        '  testCase / preconditions / no-empty-term: term must be a word or phrase, not ""',
        '  referenceDocument / body / no-empty-symbol: symbol must be a single character, not ""',
      ].join('\n'),
    )
  })
})

