    expect(response.statusCode).toBe(409)
    expect(stillThere.statusCode).toBe(200)
  })

  it('refuses a delete restating no prefix at all', async () => {
    const { app } = testlinkHolding()

    const response = await app.inject({ method: 'DELETE', url: '/projects/12' })

    expect(response.statusCode).toBe(400)
    expect(response.json().refusal).toBe('schema')
