import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import type { ReferenceDocument } from '../src/reference-document.js'
import { symbol, term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/**
 * Rules bound to both Fields of a Reference Document, so a read reports across
 * a whole document rather than one Field of it. The Test Case Rules sit beside
 * them to hold the two apart: neither may reach the other's content.
 */
const rules = [
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
  term({
    contentKind: 'referenceDocument',
    field: 'title',
    id: 'no-draft-marker',
    term: 'draft',
    reason: 'Retitle the document, or retire it.',
  }),
  symbol({
    contentKind: 'referenceDocument',
    field: 'body',
    id: 'no-spaced-dash',
    symbol: '-',
    flanked: 'whitespace',
    reason: 'A dash used as filler punctuation reads as unedited output.',
  }),
]

const roaming: ReferenceDocument = {
  title: 'Roaming between access points',
  body: 'The client reconnects after the AP restarts.',
}

/** A document the Rules fire on, as an operator can load one however it was written. */
const violating: ReferenceDocument = {
  title: 'Draft roaming notes',
  body: 'The client reconnects - the AP restarts first.',
}

/** Exercises the HTTP surface with a stubbed store. */
function serving(...held: [string, ReferenceDocument][]) {
  const documents = new StubDocumentStore()

  for (const [id, document] of held) {
    documents.hold(id, document)
  }

  return buildApp({ testlink: new StubTestLinkClient(), documents, rules })
}

describe('listing the Reference Documents', () => {
  it('lists what is there, so a caller finds a document without knowing its id', async () => {
    const app = serving(['roaming', roaming], ['ssid', { title: 'SSID naming', body: 'Name it.' }])

    const response = await app.inject({ method: 'GET', url: '/reference-documents' })

    expect(response.statusCode).toBe(200)
    expect(response.json()).toEqual([
      { id: 'roaming', title: 'Roaming between access points' },
      { id: 'ssid', title: 'SSID naming' },
    ])
  })

  it('lists nothing where no documents have been loaded, rather than refusing', async () => {
    const response = await serving().inject({ method: 'GET', url: '/reference-documents' })

    expect(response.statusCode).toBe(200)
    expect(response.json()).toEqual([])
  })
})

describe('retrieving a Reference Document', () => {
  it('serves the document whole, named by id and by nothing else', async () => {
    const app = serving(['roaming', roaming])

    const response = await app.inject({ method: 'GET', url: '/reference-documents/roaming' })

    expect(response.statusCode).toBe(200)
    expect(response.json().document).toEqual(roaming)
  })

  // The acceptance criterion this issue exists for: the agent has no local
  // files, so nothing it sends may describe one.
  it('takes no filesystem path from the caller, only the id the listing gave it', async () => {
    const app = serving(['roaming', roaming])

    const listed = await app.inject({ method: 'GET', url: '/reference-documents' })
    const [{ id }] = listed.json() as { id: string }[]
    const retrieved = await app.inject({ method: 'GET', url: `/reference-documents/${id}` })

    expect(retrieved.statusCode).toBe(200)
    expect(retrieved.json().document).toEqual(roaming)
  })

  it('serves a document nothing fired on with an empty list, not an omitted Field', async () => {
    const app = serving(['roaming', roaming])

    const response = await app.inject({ method: 'GET', url: '/reference-documents/roaming' })

    expect(response.json().violations).toEqual([])
  })
})

describe('the Violations a served Reference Document carries', () => {
  it('attaches every Violation found in it, as a Test Case read carries them', async () => {
    const app = serving(['notes', violating])

    const response = await app.inject({ method: 'GET', url: '/reference-documents/notes' })

    expect(response.json().violations).toEqual([
      {
        field: 'title',
        rule: 'no-draft-marker',
        reason: 'Retitle the document, or retire it.',
        text: 'Draft',
        offset: 0,
      },
      {
        field: 'body',
        rule: 'no-spaced-dash',
        reason: 'A dash used as filler punctuation reads as unedited output.',
        text: '-',
        offset: 22,
      },
    ])
  })

  // A read is never refused, whatever fired: refusing would put the document out
  // of reach of the caller who most needs to see what is wrong with it.
  it('serves a document the Rules fired on whole, and with a success status code', async () => {
    const app = serving(['notes', violating])

    const response = await app.inject({ method: 'GET', url: '/reference-documents/notes' })

    expect(response.statusCode).toBe(200)
    expect(response.json().document).toEqual(violating)
  })

  it('names the Rules that judged it, because the Rules took part in the answer', async () => {
    const app = serving(['notes', violating])

    const response = await app.inject({ method: 'GET', url: '/reference-documents/notes' })

    expect(response.json().ruleSetVersion).toEqual(expect.any(String))
    expect(response.headers['rule-set-version']).toEqual(expect.any(String))
  })

  // The Fields of the two do not overlap, and neither do their Rules: a Rule
  // written for a Test Case must not reach a document, or an operator loosening
  // one would silently loosen the other.
  it('runs only the Rules bound to a Reference Document, not those bound to a Test Case', async () => {
    const app = serving(['notes', { title: 'Roaming', body: 'The client will utilise the AP.' }])

    const response = await app.inject({ method: 'GET', url: '/reference-documents/notes' })

    expect(response.json().violations).toEqual([])
  })
})

describe('a Reference Document that is not there', () => {
  // A client error, told apart from a Rejection by carrying no violations at
  // all: the caller corrects the id rather than correcting content.
  it('answers a client error that cannot be read as a Rejection', async () => {
    const response = await serving().inject({ method: 'GET', url: '/reference-documents/absent' })

    expect(response.statusCode).toBe(404)
    expect(response.json()).not.toHaveProperty('violations')
  })

  it('names the id that found nothing, so the caller knows which one to correct', async () => {
    const response = await serving().inject({ method: 'GET', url: '/reference-documents/absent' })

    expect(response.json().message).toContain('absent')
  })

  // Told apart from the database being unreachable, which is the operator's to
  // recover from and answers as a server error. Status code alone separates
  // them, so a caller retries the one and escalates the other.
  it('is told apart from the database being unreachable by status code alone', async () => {
    const documents = new StubDocumentStore(false).hold('roaming', roaming)
    const app = buildApp({ testlink: new StubTestLinkClient(), documents, rules })

    const response = await app.inject({ method: 'GET', url: '/reference-documents/roaming' })

    expect(response.statusCode).toBe(500)
    expect(response.json()).not.toHaveProperty('violations')
  })
})

describe('writing a Reference Document', () => {
  // Not an oversight. A document the agent could write is a document it could
  // author in the style the Rules exist to catch and then read back as
  // authority, which is the same reason it cannot reload a Rule.
  it.each(['POST', 'PUT', 'DELETE'] as const)('is not reachable over the API (%s)', async (method) => {
    const app = serving(['roaming', roaming])

    const response = await app.inject({
      method,
      url: method === 'POST' ? '/reference-documents' : '/reference-documents/roaming',
      payload: method === 'DELETE' ? undefined : roaming,
    })

    expect(response.statusCode).toBe(404)
  })
})

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import { term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/** One Rule, which is enough to tell a Rejection from a write that lands. */
const rules = [
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
]

/** A second Rule, for reading one version against another. */
const otherRules = [
  term({
    field: 'summary',
    id: 'no-leverage',
    term: 'leverage',
    reason: 'The product documentation says use, not leverage.',
  }),
]

const clean = {
  name: 'Guest joins the open SSID',
  summary: 'The device uses the open SSID and reaches the portal.',
  preconditions: 'The open SSID is broadcast on the AP.',
}

const violating = {
  name: 'Guest joins the open SSID',
  summary: 'The device will utilise the open SSID.',
}

/** A TestLink holding one Test Case, in a Suite a write can be placed in. */
function running(supplied = rules) {
  const testlink = new StubTestLinkClient()
  testlink.hold('tc-1', clean)
  testlink.holdSuite('48')

  return buildApp({ documents: new StubDocumentStore(), testlink, rules: supplied })
}

type App = ReturnType<typeof buildApp>

const submit = (app: App, payload: Record<string, unknown>) =>
  app.inject({ method: 'POST', url: '/projects/12/suites/48/test-cases', payload })

/**
 * The version an answer names on its envelope. Read as the opaque token a caller
 * reads it as: what it is derived from is the Rule Sets' business, and a test
 * pinning its shape would be a test of how it is built rather than of what it
 * promises.
 */
const stamped = (response: Awaited<ReturnType<typeof submit>>) =>
  response.headers['rule-set-version']

describe('the Rule Set version on the envelope', () => {
  it('names the Rules on a write that lands', async () => {
    const response = await submit(running(), clean)

    expect(response.statusCode).toBe(201)
    expect(stamped(response)).toEqual(expect.any(String))
  })

  it('names the Rules on a read', async () => {
    const response = await running().inject({ method: 'GET', url: '/test-cases/tc-1' })

    expect(response.statusCode).toBe(200)
    expect(stamped(response)).toEqual(expect.any(String))
  })

  it('names the Rules on a Rejection, which is what a version is kept for', async () => {
    const response = await submit(running(), violating)

    expect(response.statusCode).toBe(422)
    expect(stamped(response)).toEqual(expect.any(String))
  })

  // The envelope is what reaches an answer carrying nothing at all, which is
  // why every answer can name the Rules rather than only the ones with a body.
  it('names the Rules on a delete, which has no body to carry them', async () => {
    const response = await running().inject({ method: 'DELETE', url: '/test-cases/tc-1' })

    expect(response.statusCode).toBe(204)
    expect(stamped(response)).toEqual(expect.any(String))
  })

  it('names the Rules on a schema refusal, which no Rule took part in', async () => {
    const response = await submit(running(), { name: clean.name })

    expect(response.statusCode).toBe(400)
    expect(stamped(response)).toEqual(expect.any(String))
  })

  it('names the Rules where TestLink held nothing to answer with', async () => {
    const response = await running().inject({ method: 'GET', url: '/test-cases/tc-9' })

    expect(response.statusCode).toBe(404)
    expect(stamped(response)).toEqual(expect.any(String))
  })
})

// Callers are agents that read the body, so an answer the Rules judged names
// the version in the answer itself rather than only on the envelope.
describe('the Rule Set version in the answer the Rules judged', () => {
  it('names it in a write that lands', async () => {
    const response = await submit(running(), clean)
    const version = stamped(response)

    expect(version).toEqual(expect.any(String))
    expect(response.json()).toEqual({ id: 'testlink-1', ruleSetVersion: version })
  })

  it('names it in a read, beside the content and the Violations', async () => {
    const response = await running().inject({ method: 'GET', url: '/test-cases/tc-1' })
    const version = stamped(response)

    expect(version).toEqual(expect.any(String))
    expect(response.json()).toEqual({
      testCase: clean,
      violations: [],
      ruleSetVersion: version,
    })
  })

  it('names it in a Rejection, so the Violations trace to the Rules that produced them', async () => {
    const response = await submit(running(), violating)
    const version = stamped(response)

    expect(version).toEqual(expect.any(String))
    expect(response.json().ruleSetVersion).toBe(version)
    expect(response.json().violations).toHaveLength(1)
  })

  it('names it in an update that lands, because an update is a write', async () => {
    const response = await running().inject({
      method: 'PUT',
      url: '/test-cases/tc-1',
      payload: clean,
    })
    const version = stamped(response)

    expect(version).toEqual(expect.any(String))
    expect(response.json()).toEqual({ id: 'tc-1', ruleSetVersion: version })
  })
})

// A schema refusal runs before any Rule, and an answer TestLink held nothing
// for consulted none: neither is the Rule Set's work, so neither claims it.
describe('the Rule Set version where no Rule ran', () => {
  it('leaves it out of a schema refusal', async () => {
    const response = await submit(running(), { name: clean.name })

    expect(response.json().refusal).toBe('schema')
    expect(response.json()).not.toHaveProperty('ruleSetVersion')
  })

  it('leaves it out of an answer TestLink held nothing for', async () => {
    const response = await running().inject({ method: 'GET', url: '/test-cases/tc-9' })

    expect(response.json()).not.toHaveProperty('ruleSetVersion')
  })
})

describe('what the Rule Set version names', () => {
  it('answers the same version for the same Rules', async () => {
    const one = await submit(running(), clean)
    const other = await submit(running(), clean)

    expect(stamped(one)).toBe(stamped(other))
  })

  // The version is derived from the Rules rather than declared alongside them,
  // so it cannot go on naming Rules that have since been changed.
  it('answers a different version once the Rules change', async () => {
    const before = await submit(running(), clean)
    const after = await submit(running(otherRules), clean)

    expect(stamped(after)).not.toBe(stamped(before))
  })

  // A disabled Rule never reaches the server, so it is absent here rather than
  // present and switched off. Switching one back on has to return the version to
  // what it was, or a version would name the history of a Rule Set rather than
  // the Rules in it.
  it('returns to the version it had when a Rule is switched off and back on', async () => {
    const both = [...rules, ...otherRules]

    const before = await submit(running(both), clean)
    const off = await submit(running(rules), clean)
    const backOn = await submit(running(both), clean)

    expect(stamped(off)).not.toBe(stamped(before))
    expect(stamped(backOn)).toBe(stamped(before))
  })

  // The database answers rows in whatever order it was asked for them, and the
  // order two Rules were written in is not something a caller was judged by.
  it('answers one version however the Rules are ordered', async () => {
    const one = await submit(running([...rules, ...otherRules]), clean)
    const other = await submit(running([...otherRules, ...rules]), clean)

    expect(stamped(other)).toBe(stamped(one))
  })

  it('answers one version across every answer a running server gives', async () => {
    const app = running()

    const written = await submit(app, clean)
    const rejected = await submit(app, violating)
    const read = await app.inject({ method: 'GET', url: '/test-cases/tc-1' })

    expect(stamped(rejected)).toBe(stamped(written))
    expect(stamped(read)).toBe(stamped(written))
  })
})

