import { Writable } from 'node:stream'

import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import { symbol, term } from './rules.js'
import { StubDocumentStore } from './stub-document-store.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

const rules = [
  term({
    field: 'summary',
    id: 'no-utilise',
    term: 'utilise',
    reason: 'The product documentation says use, not utilise.',
  }),
  symbol({
    field: 'preconditions',
    id: 'no-spaced-dash',
    symbol: '-',
    flanked: 'whitespace',
    reason: 'A dash used as filler punctuation reads as unedited output.',
  }),
]

const clean = {
  name: 'Guest joins the open SSID',
  summary: 'The device uses the open SSID and reaches the portal.',
  preconditions: 'The open SSID is broadcast on the AP.',
}

const violating = {
  name: 'Guest joins the open SSID',
  summary: 'The device will utilise the open SSID.',
  preconditions: 'Verify - the AP is broadcasting.',
}

/** What one Violation looks like in the log, as an operator would count them. */
interface Logged {
  field: string
  rule: string
  ruleSetVersion: string
}

/**
 * A server logging where a test can read it. The lines are what an operator
 * would have in front of them, so a repeatedly firing Rule is counted here the
 * way it would be counted there.
 */
function running() {
  const logged: Logged[] = []

  const stream = new Writable({
    write(chunk, _encoding, done) {
      for (const line of String(chunk).split('\n').filter(Boolean)) {
        logged.push(JSON.parse(line))
      }

      done()
    },
  })

  const testlink = new StubTestLinkClient()
  testlink.hold('tc-1', violating)
  testlink.holdSuite('48')

  return {
    logged,
    app: buildApp({ documents: new StubDocumentStore(), testlink, rules, logger: { stream, level: 'warn' } }),
  }
}

type App = ReturnType<typeof running>['app']

const submit = (app: App, payload: Record<string, unknown>) =>
  app.inject({ method: 'POST', url: '/projects/12/suites/48/test-cases', payload })

/** The Rule and Field of each Violation logged, which is what a repeat is counted by. */
const fired = (logged: Logged[]) => logged.map(({ field, rule }) => ({ field, rule }))

describe('logging the Violations a submission produced', () => {
  it('logs every Violation a Rejection carried, naming the Rule and the Field', async () => {
    const { app, logged } = running()

    await submit(app, violating)

    expect(fired(logged)).toEqual([
      { field: 'summary', rule: 'no-utilise' },
      { field: 'preconditions', rule: 'no-spaced-dash' },
    ])
  })

  // The signal a QA engineer is after: a Rule firing over and over separates a
  // Rule that cannot be satisfied from an agent that writes badly once.
  it('logs the same Rule again for a second submission, so a repeat is visible', async () => {
    const { app, logged } = running()

    await submit(app, violating)
    await submit(app, violating)

    expect(fired(logged).filter(({ rule }) => rule === 'no-utilise')).toHaveLength(2)
  })

  it('names the Rule Set version, so a firing traces to the Rules in force', async () => {
    const { app, logged } = running()

    const response = await submit(app, violating)

    expect(logged.map(({ ruleSetVersion }) => ruleSetVersion)).toEqual([
      response.headers['rule-set-version'],
      response.headers['rule-set-version'],
    ])
  })

  it('logs a Violation an update produced, because an update is a write', async () => {
    const { app, logged } = running()

    await app.inject({ method: 'PUT', url: '/test-cases/tc-1', payload: violating })

    expect(fired(logged)).toContainEqual({ field: 'summary', rule: 'no-utilise' })
  })

  it('logs nothing for a submission no Rule fired on', async () => {
    const { app, logged } = running()

    await submit(app, clean)

    expect(logged).toEqual([])
  })

  // What a read finds is a Rule firing on content already stored, not an agent
  // submitting the same mistake again, and counting it would drown the repeat.
  it('logs nothing for what a read found, because a repeat is about submissions', async () => {
    const { app, logged } = running()

    const response = await app.inject({ method: 'GET', url: '/test-cases/tc-1' })

    expect(response.json().violations).not.toEqual([])
    expect(logged).toEqual([])
  })
})

describe('what the log is allowed to reach', () => {
  // Logs are observability alone. Nothing counted here is read back, so the
  // second submission is judged by the Rules and not by its own history.
  it('answers the same Test Case identically however often it is submitted', async () => {
    const { app } = running()

    const first = await submit(app, violating)
    const second = await submit(app, violating)

    expect(second.statusCode).toBe(first.statusCode)
    expect(second.json()).toEqual(first.json())
    expect(second.headers['rule-set-version']).toBe(first.headers['rule-set-version'])
  })

  it('writes a Test Case through on a second submission as readily as the first', async () => {
    const { app } = running()

    const first = await submit(app, clean)
    const second = await submit(app, clean)

    expect(first.statusCode).toBe(201)
    expect(second.statusCode).toBe(201)
  })
})

